local config = {
  str_homestory_N26dianying_90060101_1_dialog_content = "Nah, kita di sini. Apa pun yang Anda cari harus ada di kelas ini. ya?",
  str_homestory_N26dianying_90060101_2_dialog_content = "Ahhh, sungguh membantu.",
  str_homestory_N26dianying_90060101_3_dialog_content = "Tidak sering Anda melihat anak-anak yang begitu bersemangat akhir-akhir ini.",
  str_homestory_N26dianying_90060101_4_dialog_content = "Ada apa dengan sanjungan? Jangan dipelintir, bukan karena saya benar-benar ingin berada di sini, karena saya mendengar Anda mengatakan bahwa setiap orang mungkin dalam bahaya ...",
  str_homestory_N26dianying_90060101_5_dialog_content = "Setiap orang? Kedengarannya bagus, teman mudaku yang sombong, tapi aku punya firasat yang kurang akurat.",
  str_homestory_N26dianying_90060101_6_dialog_content = "Saya menduga bahwa Anda lebih khawatir tentang gadis itu.",
  str_homestory_N26dianying_90060101_7_dialog_content = "...",
  str_homestory_N26dianying_90060101_8_dialog_content = "Ketua OSIS, hmm?",
  str_homestory_N26dianying_90060101_9_dialog_content = "B-Bagaimana kau tahu?!",
  str_homestory_N26dianying_90060101_10_dialog_content = "Jangan meremehkan intelijen departemen keamanan.",
  str_homestory_N26dianying_90060101_11_dialog_content = "Jika saya benar, ada surat cinta yang belum terkirim di saku Anda.",
  str_homestory_N26dianying_90060101_12_dialog_content = "!!!",
  str_homestory_N26dianying_90060101_13_dialog_content = "Sekarang, jangan remehkan kami.",
  str_homestory_N26dianying_90060101_14_dialog_content = "Baiklah, anak muda, bersikaplah wajar sekarang, atau Anda akan mengeluarkan kucing dari karung.",
  str_homestory_N26dianying_90060101_15_dialog_content = "Lagipula tidak ada yang akan mempercayainya, bahkan ketua OSIS yang sangat kamu sukai itu.",
  str_homestory_N26dianying_90060101_16_dialog_content = "Baiklah kalau begitu. Tebak itu yang terbaik hanya untuk pergi bersama dengan Anda.",
  str_homestory_N26dianying_90060101_17_dialog_content = "Ingat kau bilang kau akan melindunginya.",
  str_homestory_N26dianying_90060101_18_dialog_content = "Tentu saja. Dan kami selalu menghormati janji kami.",
  str_homestory_N26dianying_90060101_19_dialog_content = "Selama dia bukan orang yang kita kejar, itu saja.",
  str_homestory_N26dianying_90060101_20_dialog_content = "Ayo.",
  str_homestory_N26dianying_90060101_21_dialog_content = "Hei, apa yang kau lakukan disini, Kaseem?",
  str_homestory_N26dianying_90060101_22_dialog_content = "P-Presiden OSIS...?",
  str_homestory_N26dianying_90060101_23_dialog_content = "<size=30>Oh? Aku benar-benar tidak berharap dia ada di sini. Wah mencurigakan...</size>",
  str_homestory_N26dianying_90060101_24_dialog_content = "<size=45>Presiden! Kenapa kau di sini?</size>",
  str_homestory_N26dianying_90060101_25_dialog_content = "Seharusnya tidak mengejutkan! Aku sedang memeriksa peralatan untuk festival kampus.",
  str_homestory_N26dianying_90060101_26_dialog_content = "Wakil presiden dan siswa yang membantu di sana juga membantu dengan cek.",
  str_homestory_N26dianying_90060101_27_dialog_content = "<size=30>Saya rasa ada kemungkinan kuat bahwa benda berbahaya telah disembunyikan di antara peralatan.</size>",
  str_homestory_N26dianying_90060101_28_dialog_content = "<size=30>Jadi apa yang kamu pikirkan?</size>",
  str_homestory_N26dianying_90060101_29_dialog_content = "Hmm... aku tidak mengenali temanmu di sini, apakah dia dari sekolah kita?",
  str_homestory_N26dianying_90060101_30_dialog_content = "Temanmu di sini... sepertinya bukan bagian dari sekolah kita.",
  str_homestory_N26dianying_90060101_31_dialog_content = "Wakil Presiden...",
  str_homestory_N26dianying_90060101_32_dialog_content = "<size=30>Uh oh... Apakah dia wakil presiden yang terlalu berhati-hati?</size>",
  str_homestory_N26dianying_90060101_33_dialog_content = "<size=30>Ini mungkin tidak semudah itu, meskipun penampilannya ramah.</size>",
  str_homestory_N26dianying_90060101_34_dialog_content = "<size=30>Bantu aku memikirkan sesuatu, cepat.</size>",
  str_homestory_N26dianying_90060101_35_dialog_content = "Akan kucoba.",
  str_homestory_N26dianying_90060101_36_dialog_content = "Dia... Dia...",
  str_homestory_N26dianying_90060101_37_option_content = "Pacar perempuan",
  str_homestory_N26dianying_90060101_38_dialog_content = "Itu pacarmu! Tumbuhkan pasangan dan katakan saja!",
  str_homestory_N26dianying_90060101_39_dialog_content = "D-Dia pacarku!",
  str_homestory_N26dianying_90060101_40_dialog_content = "Eh, bukankah menurutmu itu pilihan yang cukup berbahaya, chubb.",
  str_homestory_N26dianying_90060101_41_dialog_content = "G-pacar?!",
  str_homestory_N26dianying_90060101_42_dialog_content = "Sejak kapan?!",
  str_homestory_N26dianying_90060101_43_dialog_content = "<size=30>Saya tidak berharap Anda tertarik pada saya, anak muda ...</size>",
  str_homestory_N26dianying_90060101_44_dialog_content = "<size=30>Saya tidak berharap Anda tertarik pada saya, anak muda! Tapi maafkan aku, hatiku sudah menjadi milik orang lain.</size>",
  str_homestory_N26dianying_90060101_45_dialog_content = "<size=30>Tidakkah menurut Anda alasan semacam ini terlalu jelas?</size>",
  str_homestory_N26dianying_90060101_46_dialog_content = "<size=30>Dan alasan semacam ini tidak ada gunanya untuk situasi ini.</size>",
  str_homestory_N26dianying_90060101_47_dialog_content = "M-maaf…",
  str_homestory_N26dianying_90060101_48_option_content = "Sepupu",
  str_homestory_N26dianying_90060101_49_dialog_content = "Katakan saja dia sepupumu! Naik!",
  str_homestory_N26dianying_90060101_50_dialog_content = "Oh, ini sepupuku, ya!",
  str_homestory_N26dianying_90060101_51_dialog_content = "Mereka tidak terlihat sama, hampir tidak berhubungan, chubb.",
  str_homestory_N26dianying_90060101_52_dialog_content = "Oh, sepupumu! Tidakkah Anda akan memperkenalkan kami?",
  str_homestory_N26dianying_90060101_53_dialog_content = "Oh, sepupumu, kan? Anda tidak akan memperkenalkan kami?",
  str_homestory_N26dianying_90060101_54_dialog_content = "Apakah hanya saya, atau perbedaan usia sedikit?",
  str_homestory_N26dianying_90060101_55_dialog_content = "Mau tak mau aku merasa ada sesuatu yang aneh tentang perbedaan usia.",
  str_homestory_N26dianying_90060101_56_dialog_content = "Tidak tidak. Dia selalu terlihat dewasa untuk usianya. Dia terlihat seperti ini sejak dia berusia sekitar delapan tahun.",
  str_homestory_N26dianying_90060101_57_dialog_content = "Apakah begitu? Itu benar-benar sesuatu...",
  str_homestory_N26dianying_90060101_58_dialog_content = "<size=30>Anda sedang mengobrol sampah.</size>",
  str_homestory_N26dianying_90060101_59_dialog_content = "<size=30>Ini terasa salah... Aku mulai meragukan naskahnya...</size>",
  str_homestory_N26dianying_90060101_60_dialog_content = "<size=30>Bukankah ini hanya membuat semua orang lebih fokus padaku?</size>",
  str_homestory_N26dianying_90060101_61_dialog_content = "<size=30>Lupakan saja, ini hanya akan membuat semua orang lebih fokus padaku.</size>",
  str_homestory_N26dianying_90060101_62_dialog_content = "Maaf…",
  str_homestory_N26dianying_90060101_63_option_content = "Tetangga",
  str_homestory_N26dianying_90060101_64_dialog_content = "Lebih baik katakan saja dia tetangga. Itu pasti aman!",
  str_homestory_N26dianying_90060101_65_dialog_content = "D-Dia tetangga sebelahku.",
  str_homestory_N26dianying_90060101_66_dialog_content = "Tidak bisa tidak merasa seperti sedang menggali kuburnya sendiri, chub.",
  str_homestory_N26dianying_90060101_67_dialog_content = "Tetangga?",
  str_homestory_N26dianying_90060101_68_dialog_content = "Bukankah ketua OSIS tinggal di sebelahmu?",
  str_homestory_N26dianying_90060101_69_dialog_content = "Presiden Theresa, apakah Anda mengenalinya?",
  str_homestory_N26dianying_90060101_70_dialog_content = "Tidak... Tidak, aku tidak...",
  str_homestory_N26dianying_90060101_71_dialog_content = "Apakah Anda baru saja pindah ke daerah tersebut?",
  str_homestory_N26dianying_90060101_72_dialog_content = "Oh, haha... Aku, aku membuat kesalahan.",
  str_homestory_N26dianying_90060101_73_dialog_content = "<size=30>Anda benar-benar tersesat. Tidak bisakah kamu memikirkan sesuatu yang lebih baik?</size>",
  str_homestory_N26dianying_90060101_74_dialog_content = "<size=30>Maafkan saya! Biarkan aku berpikir...</size>",
  str_homestory_N26dianying_90060101_75_dialog_content = "... Mengerti! Aku kebetulan bertemu dengannya dalam perjalanan ke sini. Dia salah satu alumni sekolah kami.",
  str_homestory_N26dianying_90060101_76_dialog_content = "Dia pernah mendengar tentang festival kampus kami, yang mengingatkannya pada waktunya di sini, jadi dia ingin ikut.",
  str_homestory_N26dianying_90060101_77_dialog_content = "Jadi begitu, mantan mahasiswa, ya?",
  str_homestory_N26dianying_90060101_78_dialog_content = "Itu menyebabkan dia terlihat lebih tua.",
  str_homestory_N26dianying_90060101_79_dialog_content = "(Bagus, Nak. Sepertinya kita sudah mengoceh untuk saat ini.)",
  str_homestory_N26dianying_90060101_80_dialog_content = "Semua peralatan sudah diperiksa, Presiden.",
  str_homestory_N26dianying_90060101_81_dialog_content = "Terima kasih.",
  str_homestory_N26dianying_90060101_82_dialog_content = "D? Laki-laki? Apakah dia akan melakukan peran silang?",
  str_homestory_N26dianying_90060101_83_dialog_content = "Betel sedang berimprovisasi.",
  str_homestory_N26dianying_90060101_84_dialog_content = "Kalau begitu silakan, silakan melihat-lihat, dan beri tahu kami jika Anda punya saran.",
  str_homestory_N26dianying_90060101_85_dialog_content = "Bagus sekali! Saya akan melihat-lihat dan menawarkan ide apa pun dari sudut pandang lulusan saya.",
  str_homestory_N26dianying_90060101_86_dialog_content = "Apa itu, Nona Presiden?!",
  str_homestory_N26dianying_90060101_87_dialog_content = "Ini adalah ... penggorengan baru yang biasa?",
  str_homestory_N26dianying_90060101_88_dialog_content = "Hah? Itu alat yang bisa menggoreng makanan tanpa perlu minyak kan?",
  str_homestory_N26dianying_90060101_89_dialog_content = "Itu benar. Keduanya sehat dan sangat populer saat ini.",
  str_homestory_N26dianying_90060101_90_dialog_content = "<size=30>Begitu... Sepertinya mudah menyembunyikan sesuatu di keranjang gorengan itu.</size>",
  str_homestory_N26dianying_90060101_91_dialog_content = "<size=30>Perangkat yang menarik juga secara hipotetis dapat dipicu oleh pemanasan.</size>",
  str_homestory_N26dianying_90060101_92_dialog_content = "<size=30>Perangkat yang menarik juga secara hipotetis dapat dipicu oleh pemanasan. Terbaik untuk melihat ke dalam.</size>",
  str_homestory_N26dianying_90060101_93_dialog_content = "Tidak terlihat bagus untuk memasak, jujur saja.",
  str_homestory_N26dianying_90060101_94_dialog_content = "Oh, ini hanya perlengkapan yang disediakan oleh klub cosplay kami.",
  str_homestory_N26dianying_90060101_95_dialog_content = "Bukankah... pabrik alkimia membuat ini?",
  str_homestory_N26dianying_90060101_96_dialog_content = "Pabrik alkimia Theresa?",
  str_homestory_N26dianying_90060101_97_dialog_content = "Sangat lucu.",
  str_homestory_N26dianying_90060101_98_dialog_content = "...",
  str_homestory_N26dianying_90060101_99_dialog_content = "(Anda mengatakan untuk memeriksa ke dalam? Pikir saya bisa?)",
  str_homestory_N26dianying_90060101_100_dialog_content = "Itu masakan spesialku!",
  str_homestory_N26dianying_90060101_101_dialog_content = "Seorang teman yang sangat baik memberi saya resepnya. Ini borscht bit.",
  str_homestory_N26dianying_90060101_102_dialog_content = "Ini menyegarkan dan menyehatkan jiwa.",
  str_homestory_N26dianying_90060101_103_dialog_content = "Bit borscht... Maksudmu...",
  str_homestory_N26dianying_90060101_104_dialog_content = "Oh, kamu pasti pernah makan borscht temanku sebelumnya, Kaseem.",
  str_homestory_N26dianying_90060101_105_dialog_content = "Aku… aku tak tahu.",
  str_homestory_N26dianying_90060101_106_dialog_content = "Ini bukan percakapan yang bagus, bagaimanapun Anda melihatnya, jadi mari kita ganti topiknya.",
  str_homestory_N26dianying_90060101_107_dialog_content = "...",
  str_homestory_N26dianying_90060101_108_dialog_content = "(Anda ingin memeriksa supnya...? Benarkah? Sebenarnya, ini cukup berbahaya.)",
  str_homestory_N26dianying_90060101_108X1_dialog_content = "Hmm... Sepertinya agak kosong disini.",
  str_homestory_N26dianying_90060101_108X2_dialog_content = "Mungkin mereka masih menyiapkan barang-barang?",
  str_homestory_N26dianying_90060101_108X3_dialog_content = "Itu mungkin, tapi aku mencium bau bahaya di dekatnya.",
  str_homestory_N26dianying_90060101_109_dialog_content = "Hah? Apa katamu?",
  str_homestory_N26dianying_90060101_110_dialog_content = "Tidak ada apa-apa. Anda terus melakukan pekerjaan Anda, saya hanya akan melihat-lihat sedikit.",
  str_homestory_N26dianying_90060101_111_dialog_content = "Oh… Baiklah.",
  str_homestory_N26dianying_90060101_112_dialog_content = "Omong-omong, Kaseem, bagaimana persiapan festival lainnya?",
  str_homestory_N26dianying_90060101_113_dialog_content = "Ah, yah, lapangan olahraga...",
  str_homestory_N26dianying_90060101_114_dialog_content = "Hai! Anda terlalu jelas. Semua orang bisa melihatmu menyelinap seperti itu!",
  str_homestory_N26dianying_90060101_115_dialog_content = "...",
  str_homestory_N26dianying_90060101_116_dialog_content = "(Apa? Anda ingin saya menemukan cara untuk memberi kita lebih banyak waktu? Apa, seperti menyembunyikan semacam detektor di topeng untuk mengendus artikel berbahaya?)",
  str_homestory_N26dianying_90060101_117_dialog_content = "(Apa? Anda ingin saya menemukan cara untuk memberi kita lebih banyak waktu? Apa, seperti menyembunyikan semacam detektor di saku untuk mencari barang berbahaya?)",
  str_homestory_N26dianying_90060101_118_dialog_content = "(Bagaimana Anda bisa menyampaikan begitu banyak hanya dengan mata Anda?)",
  str_homestory_N26dianying_90060101_119_dialog_content = "(Sebenarnya, kenapa aku bisa tahu maksudmu dengan sangat jelas?!)",
  str_homestory_N26dianying_90060101_120_dialog_content = "Drat... Perlu untuk menutupinya entah bagaimana...",
  str_homestory_N26dianying_90060101_121_dialog_content = "Ada apa, Kaseem? Apakah ada yang salah dengan matamu?",
  str_homestory_N26dianying_90060101_122_dialog_content = "Oh, Nona Presiden, saya...",
  str_homestory_N26dianying_90060101_123_option_content = "Mari bernyanyi!",
  str_homestory_N26dianying_90060101_123_dialog_content = "Tidak ada waktu! Gunakan suara Anda untuk menarik perhatiannya!",
  str_homestory_N26dianying_90060101_124_dialog_content = "Saya ingin menyanyikan lagu untuk festival kampus!",
  str_homestory_N26dianying_90060101_125_dialog_content = "Hah?",
  str_homestory_N26dianying_90060101_126_dialog_content = "Aku sudah diam-diam berlatih lagu ini dari radio. Dan saya telah berusaha keras, jadi dengarkan!",
  str_homestory_N26dianying_90060101_127_dialog_content = "Saya sebenarnya seorang penyanyi yang luar biasa, lihat saja saya mencapai semua nada tinggi!",
  str_homestory_N26dianying_90060101_128_dialog_content = "Ohh? Anda akan bernyanyi? Lalu aku akan melakukan harmoni!",
  str_homestory_N26dianying_90060101_129_dialog_content = "Ohh? Anda akan bernyanyi? Biarkan saya menemani Anda dengan lonceng ini.",
  str_homestory_N26dianying_90060101_130_dialog_content = "Tiba-tiba menyanyikan lagu seperti orang tolol.",
  str_homestory_N26dianying_90060101_131_dialog_content = "Dasar tolol... Tiba-tiba bernyanyi.",
  str_homestory_N26dianying_90060101_132_dialog_content = "Masih banyak yang harus kita persiapkan!",
  str_homestory_N26dianying_90060101_133_dialog_content = "Masih banyak yang harus kita persiapkan.",
  str_homestory_N26dianying_90060101_134_option_content = "Tolong kembalikan rekaman videonya!",
  str_homestory_N26dianying_90060101_134_dialog_content = "Anda tiba-tiba ingat video itu!",
  str_homestory_N26dianying_90060101_135_dialog_content = "Presiden!",
  str_homestory_N26dianying_90060101_136_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060101_137_dialog_content = "Bisakah Anda mengembalikan video yang saya pinjamkan kepada Anda?!",
  str_homestory_N26dianying_90060101_138_dialog_content = "Hah? Anda hanya meminjamkannya kepada saya kemarin!",
  str_homestory_N26dianying_90060101_139_dialog_content = "Dan Anda setuju untuk meminjamkan saya \"Cloud Island Ultra Warrior: The General\" selama seminggu...",
  str_homestory_N26dianying_90060101_140_dialog_content = "Dan sekarang Anda tiba-tiba membutuhkannya kembali?",
  str_homestory_N26dianying_90060101_141_dialog_content = "Sebenarnya... Aku lupa ada video lain dalam kasus ini... Sesuatu yang tidak boleh dilihat perempuan!",
  str_homestory_N26dianying_90060101_142_dialog_content = "Konten \"Railway Warrior Bros\" terlalu berdarah!",
  str_homestory_N26dianying_90060101_143_dialog_content = "Oh, a-aku mengerti…",
  str_homestory_N26dianying_90060101_144_dialog_content = "Dengar, aku akan membawa yang kanan nanti.",
  str_homestory_N26dianying_90060101_145_option_content = "Omongan!",
  str_homestory_N26dianying_90060101_145_dialog_content = "Siapa disana! Film ini untuk orang-orang dari segala usia. Lihat skalanya!",
  str_homestory_N26dianying_90060101_146_dialog_content = "Presiden Teresa!",
  str_homestory_N26dianying_90060101_147_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060101_148_dialog_content = "Apa tipemu...?",
  str_homestory_N26dianying_90060101_149_dialog_content = "K-Kenapa kau tiba-tiba menanyakan itu padaku??",
  str_homestory_N26dianying_90060101_150_dialog_content = "K-Jika kamu bersikeras... Kamu...",
  str_homestory_N26dianying_90060101_151_dialog_content = "Kamu bodoh! Mengapa saya berbicara tentang hal semacam itu di depan begitu banyak orang ?!",
  str_homestory_N26dianying_90060101_152_dialog_content = "Ahem... Itu agak rusak, Kaseem.",
  str_homestory_N26dianying_90060101_153_dialog_content = "Uh... Perlu saya permisi?",
  str_homestory_N26dianying_90060101_154_dialog_content = "Apakah ini yang disebut buku sebagai line drive?",
  str_homestory_N26dianying_90060101_155_dialog_content = "Tak usah!",
  str_homestory_N26dianying_90060101_155X1_dialog_content = "Apa yang kau bicarakan, Kaseem!?",
  str_homestory_N26dianying_90060101_156_dialog_content = "Yah, sungguh! Bagaimana menurutmu, senior, apakah hanya aku, atau apakah Kaseem bertingkah sangat aneh hari ini?",
  str_homestory_N26dianying_90060101_157_dialog_content = "Hah? Senior? Apa yang kamu cari di sana?",
  str_homestory_N26dianying_90060101_158_dialog_content = "Ups, sepertinya aku sudah kesurupan.",
  str_homestory_N26dianying_90060101_159_dialog_content = "Tidak ada apa-apa selain memulai penyelidikanku... Dengan pena berkedip yang menghapus kenangan ini!",
  str_homestory_N26dianying_90060101_160_dialog_content = "Tidak ada apa-apa selain memulai lagi, dengan kunci pas yang menghapus kenangan ini...!",
  str_homestory_N26dianying_90060101_161_dialog_content = "Apakah ini mesin penjual otomatis, Nona Presiden?",
  str_homestory_N26dianying_90060101_162_dialog_content = "Eh, iya.",
  str_homestory_N26dianying_90060101_163_dialog_content = "Saya pikir orang mungkin ingin minum untuk pergi dengan makanan ringan mereka.",
  str_homestory_N26dianying_90060101_164_dialog_content = "Jadi saya menemukan cara untuk meminjam satu secara khusus.",
  str_homestory_N26dianying_90060101_165_dialog_content = "Wow, itu cukup mengesankan. Tidak heran Anda adalah Presiden.",
  str_homestory_N26dianying_90060101_166_dialog_content = "Akulah yang mengangkutnya jauh-jauh ke sini!",
  str_homestory_N26dianying_90060101_167_dialog_content = "...",
  str_homestory_N26dianying_90060101_168_dialog_content = "(Sinyal mata lagi... Hah? Apakah area itu sudah diperiksa? Tidak ada benda berbahaya?)",
  str_homestory_N26dianying_90060101_169_dialog_content = "(Terus mengulur-ulur... Mesin penjual otomatis itu sangat mencurigakan, penuh dengan banyak minuman yang belum pernah kulihat sebelumnya!)",
  str_homestory_N26dianying_90060101_170_dialog_content = "(Susu rasa mint ikan? Rust pop? Jus sayuran?)",
  str_homestory_N26dianying_90060101_171_dialog_content = "(Apakah sekarang benar-benar waktunya untuk bertanya-tanya tentang itu ?! Saya agak di ujung tambatan saya di sini!)",
  str_homestory_N26dianying_90060101_172_dialog_content = "(Dan dari sayuran apa sebenarnya jus itu dibuat? Ini tidak seperti teh yang aneh, bukan?)",
  str_homestory_N26dianying_90060101_173_dialog_content = "Hanya harus terus berjalan...",
  str_homestory_N26dianying_90060101_174_dialog_content = "Apakah ini drum kit, Nona Presiden?",
  str_homestory_N26dianying_90060101_175_dialog_content = "Ya, tentu saja.",
  str_homestory_N26dianying_90060101_176_dialog_content = "Beberapa departemen akan mengadakan konser untuk festival, jadi mereka meninggalkannya di sini untuk saat ini.",
  str_homestory_N26dianying_90060101_177_dialog_content = "Aku tahu.",
  str_homestory_N26dianying_90060101_178_dialog_content = "...",
  str_homestory_N26dianying_90060101_179_dialog_content = "(Hal-hal yang kita cari bisa disembunyikan di dalam drum. Haruskah kita merobeknya?)",
  str_homestory_N26dianying_90060101_180_dialog_content = "(Tunggu sebentar. Jika robek, maka tidak akan berguna!)",
  str_homestory_N26dianying_90060101_182_dialog_content = "Seekor kalkun, Nona Presiden?",
  str_homestory_N26dianying_90060101_183_dialog_content = "Mengapa festival membutuhkan kalkun?",
  str_homestory_N26dianying_90060101_184_dialog_content = "Oh, itu kucing siswa... Tapi saya tidak tahu dari mana dia mendapatkan kalkun itu...",
  str_homestory_N26dianying_90060101_185_dialog_content = "Oh, benar. Anda tahu, saya pernah punya kucing yang membantu saya bekerja.",
  str_homestory_N26dianying_90060101_186_dialog_content = "...",
  str_homestory_N26dianying_90060101_187_dialog_content = "(Apa? Mungkin ada sesuatu yang disembunyikan di dalam kalkun? Kamu ingin menyelidikinya tanpa merusaknya?)",
  str_homestory_N26dianying_90060101_188_dialog_content = "(Apakah itu... bahkan mungkin? Jika Anda berhasil, Anda harus mengajari saya caranya.)",
  str_homestory_N26dianying_90060101_188X1_dialog_content = "Ini kosong...",
  str_homestory_N26dianying_90060101_188X2_dialog_content = "Apakah ini benar-benar untuk mempersiapkan festival kampus?",
  str_homestory_N26dianying_90060101_188X3_dialog_content = "Ini benar-benar tidak biasa. Ada sesuatu di sini sebelumnya.",
  str_homestory_N26dianying_90060101_188X4_dialog_content = "Ini sangat mencurigakan. Saya perlu menyelidikinya dengan hati-hati!",
  str_homestory_N26dianying_90060101_188X5_dialog_content = "Lindungi aku!",
  str_homestory_N26dianying_90060101_188X6_dialog_content = "Hah? Tapi tidak ada penutup sama sekali di sini!",
  str_homestory_N26dianying_90060101_190_option_content = "Menari!",
  str_homestory_N26dianying_90060101_190_dialog_content = "Cepat, gunakan gerakan yang sudah lama Anda latih!",
  str_homestory_N26dianying_90060101_191_dialog_content = "Lupakan!",
  str_homestory_N26dianying_90060101_192_dialog_content = "Semuanya, harap perhatikan—!",
  str_homestory_N26dianying_90060101_193_dialog_content = "Tarian saya yang luar biasa dan luar biasa!",
  str_homestory_N26dianying_90060101_193X1_dialog_content = "Apakah ini gerakan tarian berjalan planet yang legendaris? Chubb!",
  str_homestory_N26dianying_90060101_194_dialog_content = "Aaah...!!",
  str_homestory_N26dianying_90060101_195_dialog_content = "Kaseem, hari ini kamu benar-benar...",
  str_homestory_N26dianying_90060101_196_dialog_content = "Seru!",
  str_homestory_N26dianying_90060101_197_dialog_content = "Oh? Terima kasih!",
  str_homestory_N26dianying_90060101_198_dialog_content = "(Apakah dia benar-benar menyukaiku seperti ini?)",
  str_homestory_N26dianying_90060101_199_dialog_content = "Betapa bodohnya...",
  str_homestory_N26dianying_90060101_200_dialog_content = "Kau, seperti, kehilangan akal...",
  str_homestory_N26dianying_90060101_201_dialog_content = "Ada sesuatu yang sangat aneh terjadi denganmu hari ini.",
  str_homestory_N26dianying_90060101_202_dialog_content = "Luar biasa! Bisakah Anda mengajari saya cara menari, tolong!",
  str_homestory_N26dianying_90060101_203_option_content = "Telapak tangan membaca?",
  str_homestory_N26dianying_90060101_203_dialog_content = "Cepat, gunakan ilmu yang kamu pelajari dari buku...!",
  str_homestory_N26dianying_90060101_203X1_dialog_content = "Ya! Ingat poin-poin yang disebutkan dalam buku \"Mendekati Musuh Anda dengan Cepat\" sekarang ...",
  str_homestory_N26dianying_90060101_203X2_dialog_content = "Dari judul bukunya udah keliatan banyak masalah, chubb!",
  str_homestory_N26dianying_90060101_204_dialog_content = "Izinkan saya untuk membaca keberuntungan Anda di telapak tangan Anda!",
  str_homestory_N26dianying_90060101_205_dialog_content = "Maaf... Saya tidak bisa menerima itu, bahkan sebagai pengisi percakapan.",
  str_homestory_N26dianying_90060101_206_dialog_content = "Apakah kamu idiot? Lebih baik biarkan aku membaca telapak tanganmu!",
  str_homestory_N26dianying_90060101_207_dialog_content = "Sementara kita melakukannya, izinkan saya memastikan garis hidup Anda berakhir hari ini.",
  str_homestory_N26dianying_90060101_208_dialog_content = "Tentu, dan saya hanya akan memastikan bahwa garis hidup Anda benar-benar berakhir hari ini.",
  str_homestory_N26dianying_90060101_209_dialog_content = "Yah, sungguh! Bagaimana menurutmu, senior, apakah hanya aku, atau apakah Kaseem bertingkah sangat aneh hari ini?",
  str_homestory_N26dianying_90060101_210_dialog_content = "Hah? Senior? Apa yang kamu cari di sana?",
  str_homestory_N26dianying_90060101_211_dialog_content = "Ups, sepertinya aku sudah kesurupan.",
  str_homestory_N26dianying_90060101_212_dialog_content = "Tidak ada apa-apa selain memulai lagi, dengan pena yang menghapus ingatan ini...!",
  str_homestory_N26dianying_90060101_213_dialog_content = "Tidak ada apa-apa selain memulai lagi, dengan kunci pas yang menghapus kenangan ini...!",
  str_homestory_N26dianying_90060101_214_option_content = "BENDA TERBANG ANEH?",
  str_homestory_N26dianying_90060101_214_dialog_content = "Metode yang sangat tradisional biasanya yang paling efektif!",
  str_homestory_N26dianying_90060101_215_dialog_content = "Di sana! UFO!",
  str_homestory_N26dianying_90060101_216_dialog_content = "Cepat, lihat!",
  str_homestory_N26dianying_90060101_217_dialog_content = "BENDA TERBANG ANEH! Di sana!",
  str_homestory_N26dianying_90060101_218_dialog_content = "...",
  str_homestory_N26dianying_90060101_219_dialog_content = "...",
  str_homestory_N26dianying_90060101_220_dialog_content = "...",
  str_homestory_N26dianying_90060101_220X1_dialog_content = "...",
  str_homestory_N26dianying_90060101_221_dialog_content = "Yah, sungguh. Maukah Anda melihatnya, senior? Kaseem bertingkah sangat aneh hari ini.",
  str_homestory_N26dianying_90060101_222_dialog_content = "Hah? Senior? Apa yang kamu cari di sana?",
  str_homestory_N26dianying_90060101_223_dialog_content = "Ups, sepertinya aku sudah kesurupan.",
  str_homestory_N26dianying_90060101_224_dialog_content = "Tidak ada apa-apa selain memulai lagi, dengan pena yang menghapus ingatan ini...!",
  str_homestory_N26dianying_90060101_225_dialog_content = "Tidak ada apa-apa selain memulai lagi, dengan kunci pas yang menghapus kenangan ini...!",
  str_homestory_N26dianying_90060101_226_dialog_content = "...",
  str_homestory_N26dianying_90060101_227_dialog_content = "(Selesai memeriksa di sini, dan masih belum ada?)",
  str_homestory_N26dianying_90060101_228_dialog_content = "Apa ini, Nona Presiden?",
  str_homestory_N26dianying_90060101_229_dialog_content = "Oh! Saya lupa mengatakannya.",
  str_homestory_N26dianying_90060101_230_dialog_content = "Ini adalah puncak festival!",
  str_homestory_N26dianying_90060101_231_dialog_content = "Tarik saja di sini, dan mesin bertelur.",
  str_homestory_N26dianying_90060101_232_dialog_content = "Ada banyak hidangan berbeda dan lezat di dalam setiap telur. Ini alat yang luar biasa!",
  str_homestory_N26dianying_90060101_233_dialog_content = "Kapan kita mendapatkan mesin yang luar biasa...?",
  str_homestory_N26dianying_90060101_234_dialog_content = "Siswa kami yang sangat baik menyumbangkannya. Rupanya, itu cukup mahal.",
  str_homestory_N26dianying_90060101_235_dialog_content = "Hal-hal baik harus dibagikan kepada semua orang, heheh.",
  str_homestory_N26dianying_90060101_236_dialog_content = "Hal favorit semua orang ada di dalam, heheh.",
  str_homestory_N26dianying_90060101_237_dialog_content = "Mungkin kita harus mengambil kesempatan untuk mengujinya lagi, dan memberikan kesempatan kepada Kaseem dan senior kita untuk melihat betapa luar biasanya itu.",
  str_homestory_N26dianying_90060101_238_dialog_content = "<size=30>Alat ini mencurigakan dan tempat terakhir di mana sesuatu yang berbahaya bisa disembunyikan. Kita harus memanfaatkan kesempatan ini.</size>",
  str_homestory_N26dianying_90060101_239_dialog_content = "<size=30>Mengerti. Jangan khawatir.</size>",
  str_homestory_N26dianying_90060101_240_dialog_content = "Lalu, tolong...",
  str_homestory_N26dianying_90060101_243_dialog_content = "<size=30>Bagaimana mungkin... Apakah kami menerima intelijen yang buruk?</size>",
  str_homestory_N26dianying_90060101_244_dialog_content = "<size=30>Jadi apa yang kita lakukan?</size>",
  str_homestory_N26dianying_90060101_245_dialog_content = "<size=30>Mari kita keluar dari sini sekarang. Aku mungkin akan bergemuruh jika kita tinggal terlalu lama.</size>",
  str_homestory_N26dianying_90060101_246_dialog_content = "Ah, aku masih memiliki hal-hal yang harus dilakukan. Aku takut aku harus pergi.",
  str_homestory_N26dianying_90060101_247_dialog_content = "Saya berharap yang terbaik untuk festival kampus Anda.",
  str_homestory_N26dianying_90060101_248_dialog_content = "Baiklah. Terima kasih, senior.",
  str_homestory_N26dianying_90060101_249_dialog_content = "Meninggalkan, begitu saja? Ada sesuatu yang mencurigakan tentang senior ini.",
  str_homestory_N26dianying_90060101_250_dialog_content = "...",
  str_homestory_N26dianying_90060101_251_option_content = "Presiden mengoperasikannya",
  str_homestory_N26dianying_90060101_252_dialog_content = "Biarkan wanita terkemuka melakukannya!",
  str_homestory_N26dianying_90060101_253_dialog_content = "Apakah Presiden ingin mengoperasikannya?",
  str_homestory_N26dianying_90060101_254_dialog_content = "Benar-benar ingin Presiden melakukannya? Apakah kamu tidak melupakan sesuatu yang penting, chubb?",
  str_homestory_N26dianying_90060101_255_dialog_content = "Baiklah kalau begitu, aku akan membodohi diriku sendiri.",
  str_homestory_N26dianying_90060101_256_dialog_content = "Hrrrnnnng—!",
  str_homestory_N26dianying_90060101_257_dialog_content = "Ha! Saya tidak benar-benar berpikir akan ada telur.",
  str_homestory_N26dianying_90060101_258_dialog_content = "Kayak telur biasa..",
  str_homestory_N26dianying_90060101_259_dialog_content = "Ada tiramisu di dalamnya.",
  str_homestory_N26dianying_90060101_260_dialog_content = "Mungkinkah kecerdasannya salah? Apa-apa untuk itu tapi untuk terus mencari.",
  str_homestory_N26dianying_90060101_261_option_content = "Mengoperasikannya sendiri",
  str_homestory_N26dianying_90060101_262_dialog_content = "Biarkan aku yang melakukannya. Setidaknya Anda akan diyakinkan.",
  str_homestory_N26dianying_90060101_263_dialog_content = "Biar kulakukan!",
  str_homestory_N26dianying_90060101_264_dialog_content = "Tarik saja ke sini, kan?",
  str_homestory_N26dianying_90060101_265_dialog_content = "Yap.",
  str_homestory_N26dianying_90060101_266_dialog_content = "Selesai!",
  str_homestory_N26dianying_90060101_267_dialog_content = "Berkedip, dan sepertinya ada mille-feuille di dalamnya?",
  str_homestory_N26dianying_90060101_268_dialog_content = "<color=#e8d9bb>Bip — Bip —</color>",
  str_homestory_N26dianying_90060101_269_dialog_content = "Tunggu! Apa ini?!",
  str_homestory_N26dianying_90060101_270_dialog_content = "Sial, ketahuan! Lalu aku akan memiliki kalian semua—!",
  str_homestory_N26dianying_90060101_271_dialog_content = "Ada apa?!",
  str_homestory_N26dianying_90060101_272_dialog_content = "Apa yang sedang terjadi? Aku sudah menunggu semalaman untuk klimaksnya, chubb!",
  str_homestory_N26dianying_90060101_273_option_content = "Ajak senior",
  str_homestory_N26dianying_90060101_274_dialog_content = "Hmm, dia membawa alat untuk mendeteksi objek berbahaya, jadi mungkin lebih aman membiarkan senior memeriksanya.",
  str_homestory_N26dianying_90060101_275_dialog_content = "Apakah senior ingin mencoba?",
  str_homestory_N26dianying_90060101_275X1_dialog_content = "Hmm, kamu terlihat sedikit lebih pintar, chubb!",
  str_homestory_N26dianying_90060101_276_dialog_content = "Ah, pilihan bijak. Tentu, saya akan mencobanya.",
  str_homestory_N26dianying_90060101_277_dialog_content = "Telur ini memiliki suguhan lezat di dalamnya?",
  str_homestory_N26dianying_90060101_278_dialog_content = "Saya pikir itu adalah gerbang hutan hitam di dalamnya.",
  str_homestory_N26dianying_90060101_279_dialog_content = "(Hah? Detektorku bereaksi.)",
  str_homestory_N26dianying_90060101_280_dialog_content = "Tidak ada yang bergerak! Saya dengan departemen keamanan!",
  str_homestory_N26dianying_90060101_281_dialog_content = "Ini lencanaku. Sekarang, aku akan membawa semua orang untuk diinterogasi.",
  str_homestory_N26dianying_90060101_282_dialog_content = "Senior?",
  str_homestory_N26dianying_90060101_283_dialog_content = "Sial, ketahuan! Lalu aku akan memiliki kalian semua—!",
  str_homestory_N26dianying_90060101_284_dialog_content = "Eh? Apa yang kamu lakukan, siswa antusias yang tidak dikenal?",
  str_homestory_N26dianying_90060101_285_dialog_content = "Hah? Apa? Mengapa pengontrol tidak berfungsi?",
  str_homestory_N26dianying_90060101_286_dialog_content = "Hah? Apa? Mengapa pengontrol tidak berfungsi? Apakah departemen alat peraga tidak merawatnya dengan baik?",
  str_homestory_N26dianying_90060101_287_dialog_content = "Terlalu mudah tertipu, detektor di topeng saya memiliki jammer jarak kecil.",
  str_homestory_N26dianying_90060101_288_dialog_content = "Terlalu mudah tertipu, detektor saya memiliki jammer jarak kecil.",
  str_homestory_N26dianying_90060101_289_dialog_content = "Sial... Segera setelah diaktifkan, seluruh sekolah akan berubah menjadi permen, seperti rumah permen di dongeng!",
  str_homestory_N26dianying_90060101_290_dialog_content = "Aku bisa melarikan diri dengan bersembunyi di balik dinding cokelat...",
  str_homestory_N26dianying_90060101_291_dialog_content = "Jika memungkinkan, saya ingin terbang dengan kapal cokelat.",
  str_homestory_N26dianying_90060101_292_dialog_content = "... Lalu, kadar gula darah akan terlalu tinggi... Tidak! Itu terlalu berbahaya!",
  str_homestory_N26dianying_90060101_293_dialog_content = "Saya telah menonton Kerajaan Karbohidrat Anda untuk sementara waktu sekarang, jadi sebaiknya Anda semua diam-diam.",
  str_homestory_N26dianying_90060101_294_dialog_content = "Saya telah menonton Sugar Kingdom Anda untuk sementara waktu, jadi sebaiknya Anda semua diam-diam.",
  str_homestory_N26dianying_90060101_295_dialog_content = "Anda pikir Anda akan membawa saya begitu mudah?",
  str_homestory_N26dianying_90060101_296_dialog_content = "Hah? Aku tidak bisa bergerak!",
  str_homestory_N26dianying_90060101_297_dialog_content = "Aduh…!",
  str_homestory_N26dianying_90060101_298_dialog_content = "P-Presiden...!",
  str_homestory_N26dianying_90060101_299_dialog_content = "Anda...! Siswa yang antusias!",
  str_homestory_N26dianying_90060101_300_dialog_content = "Anda beruntung kali ini. Saya kira saya harus menggunakan kartu as di lengan baju saya.",
  str_homestory_N26dianying_90060101_301_dialog_content = "Tapi impian mulia kita untuk membuat orang kecanduan gula tidak akan padam!",
  str_homestory_N26dianying_90060101_302_dialog_content = "Kita lihat saja hasilnya!",
  str_homestory_N26dianying_90060101_303_dialog_content = "Tidak... aku tidak akan membiarkanmu pergi...",
  str_homestory_N26dianying_90060101_304_dialog_content = "Wakil Presiden?!",
  str_homestory_N26dianying_90060101_305_dialog_content = "Pikirkan Anda dapat menyebabkan keributan di festival kampus, dan kemudian pergi begitu saja?",
  str_homestory_N26dianying_90060101_306_dialog_content = "Apa?! Kok bisa pindah?",
  str_homestory_N26dianying_90060101_307_dialog_content = "Apa?! Kok bisa pindah? Direktur! Ini tidak benar!",
  str_homestory_N26dianying_90060101_308_dialog_content = "Siapa yang mengganggu peralatan kami? Departemen keamanan Anda tidak akan pernah bisa melakukan ini, jadi SIAPA ITU?!",
  str_homestory_N26dianying_90060101_309_dialog_content = "Rasakan ini!",
  str_homestory_N26dianying_90060101_310_dialog_content = "Serahkan semua makanan penutup!",
  str_homestory_N26dianying_90060101_311_dialog_content = "Pria yang ingin membuat semua orang ketagihan gula di festival telah dibawa pergi.",
  str_homestory_N26dianying_90060101_312_dialog_content = "Oh... Dan di sanalah aku, mengira dia benar-benar hanya murid yang rajin.",
  str_homestory_N26dianying_90060101_313_dialog_content = "Saya telah memulihkan semua makanan penutup juga.",
  str_homestory_N26dianying_90060101_314_dialog_content = "Bagaimanapun, setidaknya perdamaian telah kembali ke kampus.",
  str_homestory_N26dianying_90060101_315_dialog_content = "Tentu saja! Bagaimanapun, ini adalah kampus kami.",
  str_homestory_N26dianying_90060101_316_dialog_content = "Bukan hanya senior dari departemen keamanan. Banyak orang juga mengincarnya.",
  str_homestory_N26dianying_90060201_1_dialog_content = "Ya ampun, aku sudah terlambat! Saya hanya berharap kontaknya belum pergi ...",
  str_homestory_N26dianying_90060201_2_dialog_content = "Maaf pak, tapi apakah ini Thorngate Inn?",
  str_homestory_N26dianying_90060201_3_dialog_content = "Memang itu.",
  str_homestory_N26dianying_90060201_4_dialog_content = "Kami menyajikan semua jenis makanan di sini, cocok untuk wisatawan yang lelah.",
  str_homestory_N26dianying_90060201_5_dialog_content = "Belum lagi beberapa minuman yang tidak akan Anda temukan di tempat lain di dunia.",
  str_homestory_N26dianying_90060201_6_dialog_content = "Mengapa tidak tinggal sebentar dan mencicipi dagangan saya?",
  str_homestory_N26dianying_90060201_7_dialog_content = "Penginapan saya mungkin tidak terlihat banyak, tapi hidangan kami telah memenangkan kontes di seluruh kerajaan.",
  str_homestory_N26dianying_90060201_8_dialog_content = "Lihat? Di sana adalah trofi terbesar kita.",
  str_homestory_N26dianying_90060201_9_dialog_content = "Itu pasti trofi yang menarik ...",
  str_homestory_N26dianying_90060201_10_dialog_content = "Kami juga memiliki sejumlah karung pasir yang tersebar di seluruh penginapan.",
  str_homestory_N26dianying_90060201_11_dialog_content = "Jika mau, Anda bisa meregangkan kaki sebentar.",
  str_homestory_N26dianying_90060201_12_dialog_content = "Apa yang dilakukan hal semacam ini di penginapan...?",
  str_homestory_N26dianying_90060201_13_dialog_content = "Yah, penginapannya memang terlihat cukup bersih... Ya, kurasa aku akan tinggal sebentar.",
  str_homestory_N26dianying_90060201_14_dialog_content = "Ada kursi kosong di sana. Buat diri Anda di rumah, teman.",
  str_homestory_N26dianying_90060201_15_dialog_content = "Tempat ini cukup baik untuk dirinya sendiri. . .",
  str_homestory_N26dianying_90060201_16_dialog_content = "Ini bahkan belum jam makan, namun penginapan sudah penuh dengan pelanggan!",
  str_homestory_N26dianying_90060201_17_dialog_content = "Bagaimanapun, saya di sini untuk melihat kenalan lama, jadi saya tidak memerlukan meja saya sendiri.",
  str_homestory_N26dianying_90060201_18_dialog_content = "Nah, gayanya terlihat tidak pada tempatnya di sini.",
  str_homestory_N26dianying_90060201_19_dialog_content = "Apakah pemilik penginapan membelinya saat bepergian di negara asing?",
  str_homestory_N26dianying_90060201_20_dialog_content = "Bagaimanapun, saya di sini untuk melihat kenalan lama, jadi saya tidak memerlukan meja saya sendiri.",
  str_homestory_N26dianying_90060201_21_dialog_content = "Sekarang, itu terlalu jauh...",
  str_homestory_N26dianying_90060201_22_dialog_content = "Saya tidak berpikir selimut benar-benar diperlukan, bahkan jika cuaca sedikit dingin!",
  str_homestory_N26dianying_90060201_23_dialog_content = "Bagaimanapun, saya di sini untuk melihat seorang kenalan lama, jadi saya tidak perlu meja saya sendiri.",
  str_homestory_N26dianying_90060201_23X1_dialog_content = "Sayang sekali tokonya masih direnovasi... Bahkan tidak ada meja atau kursi.",
  str_homestory_N26dianying_90060201_23X2_dialog_content = "Karena Anda satu-satunya tamu, Anda bisa makan sambil berdiri tepat di konter.",
  str_homestory_N26dianying_90060201_23X3_dialog_content = "Apa? Anda pikir saya bisa mencapai konter !?",
  str_homestory_N26dianying_90060201_23X4_dialog_content = "Aku juga tidak tahu harus berbuat apa. Yang bisa saya lakukan adalah meminta Anda untuk mencoba menjadi lebih tinggi.",
  str_homestory_N26dianying_90060201_23X5_dialog_content = "Tidakkah menurutmu aku sedikit terlalu tua untuk terus bertambah tinggi!?",
  str_homestory_N26dianying_90060201_23X6_dialog_content = "Selain itu, benar-benar tidak ada orang di sini! Apakah saya di tempat yang tepat?",
  str_homestory_N26dianying_90060201_23X7_dialog_content = "Sial! Cari di sekitar sini lagi. Mungkin ada Thorngate Inn lain.",
  str_homestory_N26dianying_90060201_23X8_dialog_content = "...",
  str_homestory_N26dianying_90060201_24_dialog_content = "Oh begitu. Lakukan sesukamu, kalau begitu.",
  str_homestory_N26dianying_90060201_25_dialog_content = "Baiklah, sekarang mari kita bahas questnya sekali lagi...",
  str_homestory_N26dianying_90060201_26_dialog_content = "\"Pergilah ke Thorngate Inn dan hubungi prajurit misterius itu.\"",
  str_homestory_N26dianying_90060201_27_dialog_content = "\"Kerahasiaan adalah yang paling penting, jadi prajurit telah memilih untuk merahasiakan identitas mereka.\"",
  str_homestory_N26dianying_90060201_28_dialog_content = "\"Ketahuilah bahwa prajurit yang dimaksud berada di puncak kehidupan mereka dan seni bela diri mereka tidak ada duanya.\"",
  str_homestory_N26dianying_90060201_29_dialog_content = "\"Sesampai di Thorngate Inn, pesan sepanci anggur osmanthus, dan prajurit itu akan mendekatimu.\"",
  str_homestory_N26dianying_90060201_30_dialog_content = "\"Setelah kamu melakukan kontak, berikan mereka obat mujarab yang kamu miliki, dan dunia akan damai sekali lagi.\"",
  str_homestory_N26dianying_90060201_31_dialog_content = "\"Semoga berhasil, pahlawan pemberani!\"",
  str_homestory_N26dianying_90060201_32_dialog_content = "Cukup sederhana! Saya hanya harus menemukan orang yang tepat, dan pencarian saya selesai!",
  str_homestory_N26dianying_90060201_33_dialog_content = "Sekarang mari kita lihat tamu mana yang merupakan prajurit yang saya cari...",
  str_homestory_N26dianying_90060201_34_dialog_content = "Oh! O-Di sana!",
  str_homestory_N26dianying_90060201_35_dialog_content = "Berpakaian serba hitam, dengan sikap khidmat, pendiam... Seorang pejuang ulung berusaha untuk tidak menonjolkan diri!",
  str_homestory_N26dianying_90060201_36_dialog_content = "Dia pasti orang yang aku cari! Sekarang untuk langkah selanjutnya!",
  str_homestory_N26dianying_90060201_37_dialog_content = "Pemilik penginapan! Tolong sepanci anggur osmanthus terbaik Anda!",
  str_homestory_N26dianying_90060201_38_dialog_content = "Segera datang! Saya hanya akan meninggalkan ini di sini untuk Anda.",
  str_homestory_N26dianying_90060201_39_dialog_content = "Tidak banyak orang minum ini sekarang, tapi tolong nikmati.",
  str_homestory_N26dianying_90060201_40_dialog_content = "Tidak apa-apa. Beberapa hal harus dirahasiakan, bukan?",
  str_homestory_N26dianying_90060201_41_dialog_content = "Maafkan saya, tetapi apakah Anda mau minum dengan saya?",
  str_homestory_N26dianying_90060201_42_dialog_content = "... Tidak. Sekarang pergilah.",
  str_homestory_N26dianying_90060201_43_dialog_content = "Tapi ini sepanci anggur osmanthus! Osmanthus! Tidak banyak orang yang tahu tentang itu, Anda tahu?",
  str_homestory_N26dianying_90060201_44_dialog_content = "Selain itu... Kamu terlihat seperti tipe orang yang menyukai minuman seperti ini! Benar? Benar???",
  str_homestory_N26dianying_90060201_45_dialog_content = "... Siapakah Anda untuk memberi tahu saya preferensi saya sendiri?",
  str_homestory_N26dianying_90060201_46_dialog_content = "Lebih baik lagi... Siapa kamu sebenarnya?",
  str_homestory_N26dianying_90060201_47_dialog_content = "Ssst! Aku akan memberitahumu, tapi simpanlah...",
  str_homestory_N26dianying_90060201_48_dialog_content = "Sebenarnya, aku tahu siapa kamu sebenarnya...",
  str_homestory_N26dianying_90060201_49_dialog_content = "Anda lakukan?!",
  str_homestory_N26dianying_90060201_50_dialog_content = "T-Tunggu! Tenang saja, oke?",
  str_homestory_N26dianying_90060201_51_dialog_content = "Jika kau tahu siapa aku... Maka aku tidak bisa membiarkanmu hidup.",
  str_homestory_N26dianying_90060201_52_dialog_content = "Apa? Tidak! Maksudku, aku tahu kau merahasiakan identitasmu! Itu karena pencarianmu adalah yang paling penting, ingat?",
  str_homestory_N26dianying_90060201_53_dialog_content = "Saya di sini untuk membantu Anda!",
  str_homestory_N26dianying_90060201_54_dialog_content = "Tolong aku...?",
  str_homestory_N26dianying_90060201_55_dialog_content = "Dengan apa, bolehkah saya bertanya?",
  str_homestory_N26dianying_90060201_56_dialog_content = "Saya tahu seni bela diri Anda tidak ada duanya di dunia, dan Anda berada di puncak hidup Anda ...",
  str_homestory_N26dianying_90060201_57_dialog_content = "Tapi untuk melindungi dunia, ada satu hal lagi yang kau perlukan.",
  str_homestory_N26dianying_90060201_58_dialog_content = "... Apa yang kamu bicarakan?",
  str_homestory_N26dianying_90060201_59_dialog_content = "Obat mujarab, tentu saja! Saya memilikinya di sini, hanya untuk Anda!",
  str_homestory_N26dianying_90060201_60_dialog_content = "B-benarkah?!",
  str_homestory_N26dianying_90060201_61_dialog_content = "Mungkinkah ini benar-benar terjadi...?",
  str_homestory_N26dianying_90060201_62_dialog_content = "Itu benar! Maaf jika saya terlambat.",
  str_homestory_N26dianying_90060201_63_dialog_content = "Tidak apa-apa! Serahkan saja!",
  str_homestory_N26dianying_90060201_64_dialog_content = "Dengan racun ini, aku akhirnya bisa membunuh penguasa pulau dan sekali lagi membawa perdamaian ke dunia!",
  str_homestory_N26dianying_90060201_65_dialog_content = "Dengan racun ini, aku akhirnya bisa membunuh penguasa kota dan sekali lagi membawa perdamaian ke dunia!",
  str_homestory_N26dianying_90060201_66_dialog_content = "P-Racun?!",
  str_homestory_N26dianying_90060201_67_dialog_content = "Karena Anda sudah tahu siapa saya, saya kira tidak ada gunanya merahasiakannya.",
  str_homestory_N26dianying_90060201_68_dialog_content = "Tebakan Anda benar: Saya adalah pembunuh kelas dunia yang Anda cari selama ini.",
  str_homestory_N26dianying_90060201_69_dialog_content = "T-Tunggu... Aku mencari pembunuh selama ini?!",
  str_homestory_N26dianying_90060201_70_dialog_content = "Usahaku untuk membunuh penguasa pulau sejauh ini tidak membuahkan hasil, tapi dengan racun ini...",
  str_homestory_N26dianying_90060201_71_dialog_content = "Upaya saya untuk membunuh tuan kota sejauh ini tidak membuahkan hasil, tetapi dengan racun ini ...",
  str_homestory_N26dianying_90060201_72_dialog_content = "Cepat dan berikan padaku!",
  str_homestory_N26dianying_90060201_73_dialog_content = "Tidak tidak tidak! A-aku yakin ini pasti semacam kesalahpahaman!",
  str_homestory_N26dianying_90060201_74_dialog_content = "Ramuan ini sama sekali bukan racun! Di samping itu...",
  str_homestory_N26dianying_90060201_75_dialog_content = "Bukankah kita berada di negara yang terkurung daratan? Apa \"penguasa pulau\" yang kamu bicarakan?!",
  str_homestory_N26dianying_90060201_76_dialog_content = "Sekarang setelah Anda menyebutkannya, agak aneh... Saya tidak melihat lautan di mana pun di sekitar sini!",
  str_homestory_N26dianying_90060201_77_dialog_content = "Tentu saja tidak! Kami berada ribuan mil dari pantai terdekat!",
  str_homestory_N26dianying_90060201_78_dialog_content = "Pohon sakura juga berbeda... Bahkan ada buah yang tumbuh di atasnya.",
  str_homestory_N26dianying_90060201_79_dialog_content = "Apa \"pohon sakura\"?! Itu adalah pohon persik!",
  str_homestory_N26dianying_90060201_80_dialog_content = "Bukankah kita di negara terbuka? Apa \"penguasa kota\" yang kamu bicarakan?!",
  str_homestory_N26dianying_90060201_81_dialog_content = "Dari mana asalmu?",
  str_homestory_N26dianying_90060201_82_dialog_content = "Aku juga tidak yakin... Yang aku tahu, aku harus melakukan pembunuhan atas penguasa pulau itu.",
  str_homestory_N26dianying_90060201_83_dialog_content = "Aku juga tidak yakin... Yang aku tahu, adalah bahwa aku harus melakukan pembunuhan terhadap penguasa kota.",
  str_homestory_N26dianying_90060201_84_dialog_content = "Maka Anda setidaknya harus mencoba berada di tempat yang tepat!!",
  str_homestory_N26dianying_90060201_85_dialog_content = "Kamu tahu apa? Anggap saja percakapan ini tidak pernah terjadi... Maaf mengganggu Anda.",
  str_homestory_N26dianying_90060201_86_dialog_content = "Juga, coba pergi ke timur lain kali... Anda bahkan mungkin melihat lautan suatu hari nanti.",
  str_homestory_N26dianying_90060201_87_dialog_content = "Juga, coba pergi ke timur lain kali... Anda bahkan mungkin menemukan kota yang Anda cari.",
  str_homestory_N26dianying_90060201_88_dialog_content = "Tapi tunggu, racunnya...",
  str_homestory_N26dianying_90060201_89_dialog_content = "Lupakanlah! Good luck dengan misi Anda, dan selamat siang!!",
  str_homestory_N26dianying_90060201_90_dialog_content = "Ugh... Dimana sih orang yang harus kutemui ini?",
  str_homestory_N26dianying_90060201_91_dialog_content = "Aku baru saja mengacau dengan orang itu... Dia cukup misterius, tapi sama sekali tidak ada yang heroik tentang dia. Kurasa aku harus mencoba lagi...",
  str_homestory_N26dianying_90060201_92_dialog_content = "Hei... Orang itu terlihat sangat heroik bagiku!",
  str_homestory_N26dianying_90060201_93_dialog_content = "Pemilik penginapan! Panci anggur osmanthus lainnya!",
  str_homestory_N26dianying_90060201_94_dialog_content = "Segera datang! Saya hanya akan meninggalkan ini di sini untuk Anda.",
  str_homestory_N26dianying_90060201_95_dialog_content = "Tidak salah lagi... Ini pasti orang yang tepat!",
  str_homestory_N26dianying_90060201_96_dialog_content = "Maafkan saya, tetapi apakah Anda mau minum dengan saya?",
  str_homestory_N26dianying_90060201_97_dialog_content = "Oh? Dengan segala cara.",
  str_homestory_N26dianying_90060201_98_dialog_content = "Oh? Dengan segala cara.",
  str_homestory_N26dianying_90060201_99_dialog_content = "Saya memesan sepanci anggur osmanthus! Pemilik penginapan mengatakan bahwa rasanya cukup unik. Apakah ini... Sesuatu yang Anda inginkan?",
  str_homestory_N26dianying_90060201_100_dialog_content = "Ya.",
  str_homestory_N26dianying_90060201_101_dialog_content = "Suka itu? Aku menyukainya!",
  str_homestory_N26dianying_90060201_102_dialog_content = "Apa yang—?! Anda minum semuanya dalam satu tegukan!!",
  str_homestory_N26dianying_90060201_103_dialog_content = "Untuk seseorang yang sangat menyukai anggur osmanthus... Dia pasti orang yang kucari!",
  str_homestory_N26dianying_90060201_104_dialog_content = "Untuk seseorang yang sangat menyukai anggur osmanthus... Dia pasti orang yang kucari!",
  str_homestory_N26dianying_90060201_105_dialog_content = "Dengar, pahlawan, aku tahu siapa dirimu sebenarnya. Anda lihat, saya...",
  str_homestory_N26dianying_90060201_106_dialog_content = "Ssst! Tidak terlalu keras!",
  str_homestory_N26dianying_90060201_107_dialog_content = "Oh, benar! Aku hampir lupa... \"Kerahasiaan tertinggi\", dan semua itu!",
  str_homestory_N26dianying_90060201_108_dialog_content = "Anda datang untuk melakukan kontak dengan saya, ya? Aku sudah menunggu begitu lama...",
  str_homestory_N26dianying_90060201_109_dialog_content = "Ha ha ha ha! Jadi Anda akhirnya memutuskan untuk muncul!",
  str_homestory_N26dianying_90060201_110_dialog_content = "Anda datang untuk melakukan kontak dengan saya, ya?",
  str_homestory_N26dianying_90060201_111_dialog_content = "I-Itu benar! Maaf karena sangat terlambat!",
  str_homestory_N26dianying_90060201_112_dialog_content = "Jangan pikirkan itu. Selama Anda ingin menjadi bagian dari kru saya, saya dapat mengabaikannya sekali saja.",
  str_homestory_N26dianying_90060201_113_dialog_content = "Oh, jangan khawatir tentang itu!",
  str_homestory_N26dianying_90060201_114_dialog_content = "Sekarang... Selamat datang, anggota kru terbaruku!",
  str_homestory_N26dianying_90060201_115_dialog_content = "C-Kru?!",
  str_homestory_N26dianying_90060201_116_dialog_content = "Memang. Dan karena Anda yang pertama tiba, Anda memiliki hak istimewa untuk menjadi pasangan pertama saya.",
  str_homestory_N26dianying_90060201_117_dialog_content = "Mulai sekarang, Anda bisa menyebut saya sebagai \"kapten\".",
  str_homestory_N26dianying_90060201_118_dialog_content = "Memang. Dan karena Anda yang pertama tiba, Anda memiliki hak istimewa untuk menjadi pasangan pertama saya.",
  str_homestory_N26dianying_90060201_119_dialog_content = "Mulai sekarang, Anda bisa menyebut saya sebagai \"kapten\".",
  str_homestory_N26dianying_90060201_120_dialog_content = "Tunggu, tunggu, tunggu... Sepertinya ada kesalahpahaman lagi...",
  str_homestory_N26dianying_90060201_121_dialog_content = "Nakhoda macam apa kamu sebenarnya? Kami benar-benar terkurung daratan di sini, dan tidak ada kapal yang terlihat sejauh ribuan mil!",
  str_homestory_N26dianying_90060201_122_dialog_content = "Anda juga menyadarinya? Tempat ini menderita kekurangan kapal laut yang parah...",
  str_homestory_N26dianying_90060201_123_dialog_content = "Tetapi jika saya berhasil membuat kapal di sini, saya akan menjadi nakhoda pertama di seluruh kota! Suatu kehormatan bergengsi, tidakkah Anda setuju?",
  str_homestory_N26dianying_90060201_124_dialog_content = "Anda juga menyadarinya? Tempat ini menderita kekurangan kapal laut yang parah...",
  str_homestory_N26dianying_90060201_125_dialog_content = "Tetapi jika saya berhasil membuat kapal di sini, saya akan menjadi nakhoda pertama di seluruh kota! Suatu kehormatan bergengsi, tidakkah Anda setuju?",
  str_homestory_N26dianying_90060201_126_dialog_content = "Yah, sama seperti aku mengagumi semangat kepeloporanmu...",
  str_homestory_N26dianying_90060201_127_dialog_content = "Tidakkah menurutmu kekurangan kapal ada hubungannya dengan, entahlah... kekurangan perairan?!",
  str_homestory_N26dianying_90060201_128_dialog_content = "Heh... Sebuah kapal tidak MEMBUTUHKAN air untuk bisa berlayar.",
  str_homestory_N26dianying_90060201_129_dialog_content = "Heh... Sebuah kapal tidak MEMBUTUHKAN air untuk bisa berlayar.",
  str_homestory_N26dianying_90060201_130_dialog_content = "Apa maksudnya itu?!",
  str_homestory_N26dianying_90060201_131_dialog_content = "Yakinlah, saya telah mempertimbangkan semua pertanyaan ini.",
  str_homestory_N26dianying_90060201_132_dialog_content = "Yakinlah, saya telah mempertimbangkan semua pertanyaan ini.",
  str_homestory_N26dianying_90060201_133_dialog_content = "Betulkah? Karena saya mohon berbeda!",
  str_homestory_N26dianying_90060201_134_dialog_content = "Setelah cukup banyak orang bergabung dengan kru kami, kami dapat meminta dukungan kerajaan! Semuanya akan berhasil begitu kita mencapai titik itu!",
  str_homestory_N26dianying_90060201_135_dialog_content = "Setelah cukup banyak orang bergabung dengan kru kami, kami dapat meminta dukungan kerajaan! Semuanya akan berhasil begitu kita mencapai titik itu!",
  str_homestory_N26dianying_90060201_136_dialog_content = "... Kamu tahu apa? Saya baru ingat saya sangat mudah mabuk laut! Juga, saya memiliki beberapa bisnis lain untuk dihadiri!",
  str_homestory_N26dianying_90060201_137_dialog_content = "Aku akan pergi sekarang!",
  str_homestory_N26dianying_90060201_138_dialog_content = "Tapi tunggu, bagaimana dengan menjadi teman pertamaku?",
  str_homestory_N26dianying_90060201_139_dialog_content = "Tapi tunggu, bagaimana dengan menjadi teman pertamaku?",
  str_homestory_N26dianying_90060201_140_dialog_content = "Aku benar-benar tidak cocok untuk kehidupan petualang, aku janji! Semoga berhasil!",
  str_homestory_N26dianying_90060201_141_dialog_content = "Astaga... Apakah ada satu orang normal pun di tempat ini?!",
  str_homestory_N26dianying_90060201_142_dialog_content = "Siapa lagi yang bisa itu...?",
  str_homestory_N26dianying_90060201_143_dialog_content = "Oh tidak... Hanya ada satu orang yang belum kutanyai.",
  str_homestory_N26dianying_90060201_144_dialog_content = "Tapi mereka sama sekali tidak cocok dengan deskripsi quest... Apa yang harus kulakukan?",
  str_homestory_N26dianying_90060201_145_dialog_content = "Ah, lupakan saja... Aku sudah di sini, jadi sebaiknya aku mencobanya.",
  str_homestory_N26dianying_90060201_146_dialog_content = "Pemilik penginapan! Tolong, satu panci lagi!",
  str_homestory_N26dianying_90060201_147_dialog_content = "Baiklah, tapi... Anda tahu ini pot ketiga Anda, bukan?",
  str_homestory_N26dianying_90060201_148_dialog_content = "Saya tidak tahu Anda sangat menikmati anggur osmanthus.",
  str_homestory_N26dianying_90060201_149_dialog_content = "T-Sejujurnya, aku bahkan belum menyesapnya...",
  str_homestory_N26dianying_90060201_150_dialog_content = "Tolong biarkan pelanggan yang tampak aneh ini menjadi orang yang saya cari...",
  str_homestory_N26dianying_90060201_151_dialog_content = "Maafkan saya, tetapi apakah Anda ingin—",
  str_homestory_N26dianying_90060201_152_dialog_content = "Anda akhirnya di sini!",
  str_homestory_N26dianying_90060201_153_dialog_content = "Hah?!",
  str_homestory_N26dianying_90060201_154_dialog_content = "M-Maaf, tanggapanmu membuatku lengah...",
  str_homestory_N26dianying_90060201_155_dialog_content = "Anda tahu siapa saya, kan?",
  str_homestory_N26dianying_90060201_156_dialog_content = "Saya lakukan? Maaf, tapi aku tidak bisa memastikan apa-apa lagi...",
  str_homestory_N26dianying_90060201_157_dialog_content = "Dua orang terakhir yang saya dekati adalah... sesuatu yang lain.",
  str_homestory_N26dianying_90060201_158_dialog_content = "Saya datang dari seribu tahun di masa depan!",
  str_homestory_N26dianying_90060201_159_dialog_content = "Dan kamu tidak berbeda!!!",
  str_homestory_N26dianying_90060201_160_dialog_content = "Saya terdampar pada titik ini setelah kesalahan input menyebabkan teleporter saya tidak berfungsi secara kritis.",
  str_homestory_N26dianying_90060201_161_dialog_content = "Tapi kau di sini untuk membawaku kembali, kan?",
  str_homestory_N26dianying_90060201_162_dialog_content = "... Aku tidak mengerti satu kata pun yang keluar dari mulutmu barusan.",
  str_homestory_N26dianying_90060201_163_dialog_content = "Tunggu, jadi kamu TIDAK akan membawaku kembali ke waktuku? Cacat.",
  str_homestory_N26dianying_90060201_164_dialog_content = "Aaargh! Aku benar-benar gagal dalam pencarianku!",
  str_homestory_N26dianying_90060201_165_dialog_content = "Pencarian?",
  str_homestory_N26dianying_90060201_166_dialog_content = "Pencarian? Pencarian apa?",
  str_homestory_N26dianying_90060201_167_dialog_content = "Oh, lupakan saja... Itu tidak penting lagi.",
  str_homestory_N26dianying_90060201_168_dialog_content = "Maaf, tapi saya bukan orang yang Anda cari.",
  str_homestory_N26dianying_90060201_169_dialog_content = "Tetap saja, aku harus bertanya... Apa yang dilakukan seseorang dari masa depan di tempat seperti ini?",
  str_homestory_N26dianying_90060201_170_dialog_content = "Seribu tahun ke depan, laboratorium saya terletak di lokasi ini.",
  str_homestory_N26dianying_90060201_171_dialog_content = "Itu karena lab saya berada di tempat yang tepat ini! Hanya seribu tahun di masa depan, tentu saja.",
  str_homestory_N26dianying_90060201_172_dialog_content = "Ngomong-ngomong, rekan peneliti saya harus segera datang untuk menyelamatkan saya... Sebentar lagi.",
  str_homestory_N26dianying_90060201_173_dialog_content = "Jadi itu sebabnya kamu menunggu di sini selama ini? Apakah tidak ada cara lain untuk kembali ke waktu Anda?",
  str_homestory_N26dianying_90060201_174_dialog_content = "Yah, aku bisa menunggu seribu tahun lagi?",
  str_homestory_N26dianying_90060201_175_dialog_content = "Tidak terlalu. Saya tidak dapat menghubungi kolega saya sama sekali sejak saat ini.",
  str_homestory_N26dianying_90060201_176_dialog_content = "Jika saya tidak dapat menjangkau mereka, maka saya harus menunggu sampai laboratorium dibangun kembali.",
  str_homestory_N26dianying_90060201_177_dialog_content = "Anda hanya akan duduk di sini selama satu milenium ?!",
  str_homestory_N26dianying_90060201_178_dialog_content = "Jika itu yang dibutuhkan, maka ya.",
  str_homestory_N26dianying_90060201_179_dialog_content = "Itu, uh... Akan membutuhkan banyak kesabaran.",
  str_homestory_N26dianying_90060201_180_dialog_content = "Sigh... Andai saja pahlawanku memiliki kesabaran seperti itu!",
  str_homestory_N26dianying_90060201_181_dialog_content = "Tetap saja, saya tidak menyalahkan mereka karena tidak berada di sini. Jika ada, itu salahku karena terlambat ...",
  str_homestory_N26dianying_90060201_182_dialog_content = "Anda selalu bisa menghabiskan seribu tahun berikutnya menemani saya?",
  str_homestory_N26dianying_90060201_183_dialog_content = "Gan, terima kasih atas tawaran baiknya...",
  str_homestory_N26dianying_90060201_184_dialog_content = "Saya hanya berharap saya bisa optimis tentang hal-hal seperti Anda ...",
  str_homestory_N26dianying_90060201_185_dialog_content = "Hai! Dengarkan, dasar babi yang puas diri!",
  str_homestory_N26dianying_90060201_186_dialog_content = "Hah? Ada apa dengan semua teriakan di luar?",
  str_homestory_N26dianying_90060201_187_dialog_content = "Gunung ini milikku, kau dengar?",
  str_homestory_N26dianying_90060201_188_dialog_content = "Jika Anda memiliki otak di antara telinga Anda, tinggalkan barang berharga Anda dan tersesat! Jika tidak, saya akan menghancurkan otak kecil apa yang Anda miliki di tanah!",
  str_homestory_N26dianying_90060201_189_dialog_content = "Bandit?! Ah, ini buruk!",
  str_homestory_N26dianying_90060201_190_dialog_content = "Saya tidak cocok untuk mereka semua sekaligus! Aku harus mencari jalan keluar dari sini...",
  str_homestory_N26dianying_90060201_191_dialog_content = "Sial... Jika aku melawan mereka, penyamaranku akan terbongkar. Saatnya mundur...",
  str_homestory_N26dianying_90060201_192_dialog_content = "Itu cepat!!",
  str_homestory_N26dianying_90060201_193_dialog_content = "Oh bagus! Lihat saja semua wajah bersemangat itu! Mereka pasti datang untuk bergabung dengan kru saya!",
  str_homestory_N26dianying_90060201_194_dialog_content = "Aku harus pergi menyapa mereka!",
  str_homestory_N26dianying_90060201_195_dialog_content = "Oh bagus! Lihat saja semua wajah bersemangat itu! Mereka pasti datang untuk bergabung dengan kru saya!",
  str_homestory_N26dianying_90060201_196_dialog_content = "Aku harus pergi menyapa mereka!",
  str_homestory_N26dianying_90060201_197_dialog_content = "G-Kembali ke sini! Apakah Anda tidak memiliki pegangan sedikit pun pada kenyataan ?!",
  str_homestory_N26dianying_90060201_198_dialog_content = "Ini tidak akan berhasil... Aku tidak bisa membiarkan gerombolan bandit mengambil alih lokasi laboratorium di masa depan.",
  str_homestory_N26dianying_90060201_199_dialog_content = "Aku akan pergi memusnahkan mereka.",
  str_homestory_N26dianying_90060201_200_dialog_content = "Sendiri? Tapi sepertinya ada banyak dari mereka di luar sana!",
  str_homestory_N26dianying_90060201_201_dialog_content = "Wah...Begitu saja, yang tersisa di sini hanya pemilik penginapan dan saya sendiri...",
  str_homestory_N26dianying_90060201_202_dialog_content = "Ini bukan hariku... Pertama aku gagal melakukan kontak dengan orang yang tepat, lalu kami diserang oleh bandit...",
  str_homestory_N26dianying_90060201_203_dialog_content = "Apakah saya masih perlu membayar tab saya jika kita semua akhirnya mati?",
  str_homestory_N26dianying_90060201_204_dialog_content = "Jadi Anda sudah menyerah pada pencarian Anda, bukan?",
  str_homestory_N26dianying_90060201_205_dialog_content = "Yeah... Kurasa ini saatnya menerima takdirku...",
  str_homestory_N26dianying_90060201_206_dialog_content = "T-Tunggu, bagaimana kau tahu tentang itu?!",
  str_homestory_N26dianying_90060201_207_dialog_content = "Pencarian saya seharusnya sangat rahasia!",
  str_homestory_N26dianying_90060201_208_dialog_content = "Orang yang kamu cari ada di sini selama ini...",
  str_homestory_N26dianying_90060201_209_dialog_content = "Tapi itu tidak serta merta menjadikan mereka pelanggan.",
  str_homestory_N26dianying_90060201_210_dialog_content = "Tunggu, kau tidak bermaksud...",
  str_homestory_N26dianying_90060201_211_dialog_content = "Mungkinkah...?!",
  str_homestory_N26dianying_90060201_212_dialog_content = "Apakah ANDA prajurit yang harus saya temui ?!",
  str_homestory_N26dianying_90060201_213_dialog_content = "Mustahil! Ini tidak mungkin!",
  str_homestory_N26dianying_90060201_214_dialog_content = "Orang dalam pencarian seharusnya \"di puncak kehidupan mereka\"! Seni bela diri mereka seharusnya tidak ada duanya! Tapi kamu...",
  str_homestory_N26dianying_90060201_215_dialog_content = "Wajahmu sangat lusuh... Dan kamu dikurung di kursi roda! Bagaimana Anda bisa menjadi orang yang saya cari ?!",
  str_homestory_N26dianying_90060201_216_dialog_content = "Heh, deskripsi yang cukup fantastis... Tapi cocok, sama saja. Prajurit yang Anda datangi ke sini untuk menemukan tidak lain adalah milik Anda sebenarnya.",
  str_homestory_N26dianying_90060201_217_dialog_content = "Hanya... Kamu datang terlambat.",
  str_homestory_N26dianying_90060201_218_dialog_content = "Terlambat sepuluh tahun, sebenarnya!",
  str_homestory_N26dianying_90060201_219_dialog_content = "Sepuluh tahun?!",
  str_homestory_N26dianying_90060201_220_dialog_content = "Apa?!?",
  str_homestory_N26dianying_90060201_221_dialog_content = "Kaki saya terluka parah sepuluh tahun yang lalu, jadi saya bersembunyi di sini. Saya telah menunggu seorang pahlawan membawakan saya ramuan penyembuhan.",
  str_homestory_N26dianying_90060201_222_dialog_content = "Tapi tidak peduli berapa lama aku menunggu... Pahlawan itu tidak pernah datang.",
  str_homestory_N26dianying_90060201_223_dialog_content = "Banyak yang telah berubah dalam sepuluh tahun terakhir. Saya memaksakan diri untuk minum anggur osmanthus setiap hari, dan akhirnya, saya merasakannya.",
  str_homestory_N26dianying_90060201_224_dialog_content = "Karena obat mujarab tidak pernah datang, kaki saya berangsur-angsur memburuk, dan saya berakhir di kursi roda.",
  str_homestory_N26dianying_90060201_225_dialog_content = "Saya menjadi teman dekat dengan pemilik sebelumnya dari penginapan ini, dan ketika dia akhirnya meninggal... Saya terkejut mengetahui bahwa dia telah mempercayakannya kepada saya.",
  str_homestory_N26dianying_90060201_226_dialog_content = "Saya tidak pernah menyangka, setelah sekian lama, Anda masih akan muncul.",
  str_homestory_N26dianying_90060201_227_dialog_content = "Oh, anu...",
  str_homestory_N26dianying_90060201_228_option_content = "Minta maaf dengan tulus",
  str_homestory_N26dianying_90060201_229_dialog_content = "Jangan hanya berdiri di sana! Minta maaf, sekarang juga!",
  str_homestory_N26dianying_90060201_230_dialog_content = "M-Maafkan aku, pahlawan pemberani! Dari lubuk hatiku, aku sangat menyesal!",
  str_homestory_N26dianying_90060201_231_dialog_content = "A-Kalau saja aku tidak begitu terlambat ...",
  str_homestory_N26dianying_90060201_232_dialog_content = "Anda sepuluh tahun \"terlambat\"? Tidakkah menurut Anda itu sedikit meremehkan?",
  str_homestory_N26dianying_90060201_233_dialog_content = "Ini semua salahku... Aku salah menempatkan gulungan pencarian di suatu tempat di rumahku...",
  str_homestory_N26dianying_90060201_234_dialog_content = "Baru setelah saya mulai berkemas untuk pindah, saya akhirnya menemukannya. Satu-satunya masalah adalah saya lupa berapa umur sebenarnya permintaan itu ...",
  str_homestory_N26dianying_90060201_235_dialog_content = "Tidak apa-apa. Seandainya ini terjadi beberapa tahun yang lalu, saya mungkin kesal, tetapi sekarang ... Saya tidak bisa tidak menganggapnya lucu. Tertawa, bahkan.",
  str_homestory_N26dianying_90060201_236_dialog_content = "Anda tampaknya benar-benar tulus, jadi saya tidak akan melanjutkan masalah ini. Hari-hari petualangan saya jauh di belakang saya; Saya hanya ingin menghabiskan sisa hidup saya dengan damai.",
  str_homestory_N26dianying_90060201_237_dialog_content = "Tetap saja, saya meninggalkan beberapa hal yang belum selesai di masa lalu... Jika Anda benar-benar ingin menebus kesalahan, Anda dapat mengurusnya sebagai pengganti saya?",
  str_homestory_N26dianying_90060201_238_dialog_content = "Betulkah? Tentu saja, saya akan dengan senang hati membantu!",
  str_homestory_N26dianying_90060201_239_dialog_content = "Mitra lama saya dari hari-hari petualangan saya tinggal di dekatnya. Sama seperti saya, dia telah memilih untuk merahasiakan identitasnya, dan bekerja di pasar.",
  str_homestory_N26dianying_90060201_240_dialog_content = "Saya punya surat untuknya, dan saya ingin Anda memenuhi misi saya dengan mengirimkannya kepadanya.",
  str_homestory_N26dianying_90060201_241_dialog_content = "Dipahami! Saya hanya perlu bertemu dengan kontak anonim lainnya, bukan? Saya pasti memiliki pengalaman dengan pencarian semacam ini sekarang!",
  str_homestory_N26dianying_90060201_242_dialog_content = "Saya tentu berharap demikian.",
  str_homestory_N26dianying_90060201_243_dialog_content = "Tidak ada ruang untuk \"keterlambatan\" Anda lagi dalam hal pengiriman surat ini.",
  str_homestory_N26dianying_90060201_244_dialog_content = "Orang yang dimaksud bahkan lebih tua dari saya. Saya ragu dia akan hidup untuk melihat satu dekade lagi berlalu.",
  str_homestory_N26dianying_90060201_245_option_content = "Buat alasan",
  str_homestory_N26dianying_90060201_246_dialog_content = "Apakah kamu lupa? Pikirkan tentang alasan Anda begitu terlambat!",
  str_homestory_N26dianying_90060201_247_dialog_content = "Oh, benar! Itu karena aku memiliki terlalu banyak quest di tanganku!",
  str_homestory_N26dianying_90060201_248_dialog_content = "Anda tahu, dengan keadaan tanah yang berantakan, saya memiliki begitu banyak pahlawan yang menghubungi saya sehingga saya tidak dapat melacak mereka semua!",
  str_homestory_N26dianying_90060201_249_dialog_content = "Beberapa dari mereka sudah berada di ambang kematian, jadi saya harus memprioritaskan mereka.",
  str_homestory_N26dianying_90060201_250_dialog_content = "U-Sayangnya... Karena itu butuh waktu lama bagiku untuk datang mencarimu.",
  str_homestory_N26dianying_90060201_251_dialog_content = "Apakah begitu? Aku tidak tahu ada begitu banyak pahlawan dalam kesulitan...",
  str_homestory_N26dianying_90060201_252_dialog_content = "Mengapa Anda tidak menyebutkan beberapa dari mereka untuk saya? Siapa tahu, mungkin saya mengenal mereka di zaman saya?",
  str_homestory_N26dianying_90060201_253_dialog_content = "Saya akan merasa jauh lebih baik mengetahui bahwa rekan-rekan lama saya diurus, bahkan jika itu dengan biaya saya sendiri.",
  str_homestory_N26dianying_90060201_254_dialog_content = "T-Tentu, sebentar...",
  str_homestory_N26dianying_90060201_255_dialog_content = "Luangkan semua waktu yang Anda butuhkan. Lagipula, aku menunggu sepuluh tahun untukmu... Aku bisa menunggu sepuluh tahun lagi.",
  str_homestory_N26dianying_90060201_256_dialog_content = "Jika Anda tidak dapat mengingat nama mereka, mungkin saya dapat memperkenalkan beberapa dari mereka kepada Anda? Itu mungkin akan mengganggu ingatanmu...",
  str_homestory_N26dianying_90060201_257_dialog_content = "S-Memperkenalkan saya kepada mereka?",
  str_homestory_N26dianying_90060201_258_dialog_content = "Itu benar, meski seharusnya aku tidak menyebut mereka \"pahlawan\" lagi. Anda lihat, beberapa dari mereka mulai menempuh jalan yang salah di masa lalu...",
  str_homestory_N26dianying_90060201_259_dialog_content = "Nyatanya, saya yakin beberapa dari mereka berdiri tepat di depan pintu saya, menunggu kesempatan untuk membicarakan masa lalu yang indah.",
  str_homestory_N26dianying_90060201_260_dialog_content = "Maksudmu bukan para bandit... Benarkah?!",
  str_homestory_N26dianying_90060201_261_dialog_content = "Tidak, tolong! Aku tidak ingin bertemu mereka!",
  str_homestory_N26dianying_90060201_262_dialog_content = "Saya salah, Tuan Pemilik Penginapan! Maafkan saya!!!",
  str_homestory_N26dianying_90060201_263_option_content = "Selesaikan pencarian",
  str_homestory_N26dianying_90060201_264_dialog_content = "Jangan lupa! Anda masih memiliki misi untuk diselesaikan!",
  str_homestory_N26dianying_90060201_265_dialog_content = "Tidak ada yang penting sekarang! Saya telah membawakan Anda obat mujarab yang Anda minta, pahlawan pemberani!",
  str_homestory_N26dianying_90060201_266_dialog_content = "Dan sementara saya agak terlambat dengan pengirimannya... Quest saya akhirnya selesai!",
  str_homestory_N26dianying_90060201_267_dialog_content = "\"Agak terlambat,\" katamu?",
  str_homestory_N26dianying_90060201_268_dialog_content = "Saya tidak tahu satu dekade adalah waktu yang sangat sedikit ...",
  str_homestory_N26dianying_90060201_269_dialog_content = "Aku benar-benar minta maaf soal itu... Hanya saja aku salah menaruh gulungan misi di suatu tempat di rumahku...",
  str_homestory_N26dianying_90060201_270_dialog_content = "Baru setelah saya mulai berkemas untuk pindah, saya akhirnya menemukannya. Satu-satunya masalah adalah saya lupa berapa umur sebenarnya permintaan itu ...",
  str_homestory_N26dianying_90060201_271_dialog_content = "Bagaimanapun, saya membawanya sejauh ini, jadi ini dia. Siapa tahu, itu mungkin hanya memperbaiki kaki Anda!",
  str_homestory_N26dianying_90060201_272_dialog_content = "Dengan cara ini, saya dapat menyerahkan pencarian saya ketika saya kembali.",
  str_homestory_N26dianying_90060201_273_dialog_content = "Aku sudah tidak membutuhkannya lagi. Kakiku sudah mati, dan tidak ada obat mujarab yang bisa menyembuhkannya.",
  str_homestory_N26dianying_90060201_274_dialog_content = "Simpan saja untuk dirimu sendiri. Anda mungkin akan membutuhkannya suatu hari nanti.",
  str_homestory_N26dianying_90060201_275_dialog_content = "Saya tidak tahu tentang itu... Selain itu, saya tidak dapat menyerahkan pencarian saya jika Anda tidak menerimanya.",
  str_homestory_N26dianying_90060201_276_dialog_content = "Yah, kebetulan kami dikelilingi oleh sekelompok bandit haus darah...",
  str_homestory_N26dianying_90060201_277_dialog_content = "Saya pikir Anda mungkin membutuhkannya lebih dari yang Anda pikirkan segera.",
  str_homestory_N26dianying_90060201_278_dialog_content = "Apa?!?",
  str_homestory_N26dianying_90060201_279_dialog_content = "Tidak, tolong! Selamatkan aku, pahlawan yang hebat dan penyayang!",
  str_homestory_N26dianying_90060201_280_dialog_content = "Pemilik penginapan! Tolong sepanci anggur osmanthus terbaik Anda!",
  str_homestory_N26dianying_90060201_281_dialog_content = "Maaf, tapi kami semua keluar.",
  str_homestory_N26dianying_90060201_282_dialog_content = "Apa? \"Segalanya\"?!",
  str_homestory_N26dianying_90060201_283_dialog_content = "Itu benar. Saya tidak memiliki setetes barang di tangan saat ini.",
  str_homestory_N26dianying_90060201_284_dialog_content = "Bagaimana Anda bisa kehabisan pada saat seperti ini? Semuanya hancur sekarang!",
  str_homestory_N26dianying_90060201_285_dialog_content = "Saya selalu bisa mengirimkan beberapa, jika Anda mau?",
  str_homestory_N26dianying_90060201_286_dialog_content = "Jika Anda sangat ingin menikmati anggur jenis ini hari ini, saya dapat memesannya dari toko tetangga. Ini akan memakan waktu, tetapi itu bisa dilakukan.",
  str_homestory_N26dianying_90060201_287_dialog_content = "B-benarkah?",
  str_homestory_N26dianying_90060201_288_dialog_content = "Baiklah, aku bisa menunggu!",
  str_homestory_N26dianying_90060201_289_dialog_content = "Anggur osmanthus ini memiliki rasa yang sangat unik. Tidak banyak orang minum ini sekarang, tapi tolong nikmati.",
  str_homestory_N26dianying_90060201_290_dialog_content = "Tetap saja, hatiku senang melihat orang lain yang menghargai minuman favoritku.",
  str_homestory_N26dianying_90060201_291_dialog_content = "Tolong sisihkan saja saat sudah sampai di sini. Semuanya akan hancur jika saya tidak memiliki panci itu ...",
  str_homestory_N26dianying_90060201_292_dialog_content = "<color=#e8d9bb>Tok, tok, tok!</color>",
  str_homestory_N26dianying_90060201_293_dialog_content = "Seseorang di pintu! Apakah mereka membawa anggur osmanthus?",
  str_homestory_N26dianying_90060201_294_dialog_content = "Ssst! Suara itu...",
  str_homestory_N26dianying_90060201_295_dialog_content = "Hai! Dengarkan, dasar babi yang puas diri!",
  str_homestory_N26dianying_90060201_296_dialog_content = "Gunung ini milikku, kau dengar?",
  str_homestory_N26dianying_90060201_297_dialog_content = "Jika Anda memiliki otak di antara telinga Anda, tinggalkan barang berharga Anda dan tersesat! Jika tidak, saya akan menghancurkan otak kecil apa yang Anda miliki di tanah!",
  str_homestory_N26dianying_90060201_298_dialog_content = "Bandit? Sekarang, sepanjang masa?!",
  str_homestory_N26dianying_90060201_299_dialog_content = "Sial... Jika aku melawan mereka, penyamaranku akan terbongkar. Saatnya mundur...",
  str_homestory_N26dianying_90060201_300_dialog_content = "Oh bagus! Aku akan pergi menyapa mereka!",
  str_homestory_N26dianying_90060201_301_dialog_content = "Oh bagus! Aku akan pergi menyapa mereka!",
  str_homestory_N26dianying_90060201_302_dialog_content = "Basmi mereka semua.",
  str_homestory_N26dianying_90060201_303_dialog_content = "Sayangnya, tampaknya penginapanku yang sederhana akan dijarah oleh sekelompok bandit.",
  str_homestory_N26dianying_90060201_304_dialog_content = "Nah, jika Anda akan berbaik hati untuk melarikan diri dari belakang ...",
  str_homestory_N26dianying_90060201_305_dialog_content = "Yah, aku ingin melarikan diri dengan hidup saya dan semua ...",
  str_homestory_N26dianying_90060201_306_dialog_content = "Tapi bagaimana dengan pencarianku?!",
  str_homestory_N26dianying_90060301_1_dialog_content = "Api perang telah merusak dunia kita selama bertahun-tahun sekarang... Dengan berlalunya hari, perjuangan kita melawan Eclipsites tampaknya semakin sia-sia.",
  str_homestory_N26dianying_90060301_2_dialog_content = "Hanya Pedang Surgawi yang telah lama hilang, senjata suci dan kuat, yang dapat mengakhiri perselisihan dan sekali lagi membawa perdamaian ke dunia.",
  str_homestory_N26dianying_90060301_3_dialog_content = "... Atau begitulah kata legenda. Bukankah itu benar, hamba yang setia?",
  str_homestory_N26dianying_90060301_4_dialog_content = "<size=45>Baik tuan ku!</size>",
  str_homestory_N26dianying_90060301_5_dialog_content = "Argh, telingaku! Pelankan suaramu, bodoh!",
  str_homestory_N26dianying_90060301_6_dialog_content = "Ahem... Sebagai utusan Dragonscorch, kekuatan paling kuat di negeri ini, aku punya alasan untuk memanggilmu ke sini hari ini.",
  str_homestory_N26dianying_90060301_7_dialog_content = "Meskipun baru saja bergabung dengan faksi kami, Anda telah membuktikan diri Anda sebagai pelayan yang setia dan cakap.",
  str_homestory_N26dianying_90060301_8_dialog_content = "Nah, legenda juga mengatakan bahwa Pedang Langit terakhir terlihat di Desa Naga. Dari apa yang saya mengerti, Anda juga berasal dari desa yang sama, bukan?",
  str_homestory_N26dianying_90060301_9_dialog_content = "<size=45>Baik tuan ku!</size>",
  str_homestory_N26dianying_90060301_10_dialog_content = "Luar biasa... Maka dengan ini saya mempercayakan Anda dengan tugas suci: kembali ke Desa Naga, dan temukan Pisau Surgawi di tempat saya.",
  str_homestory_N26dianying_90060301_11_dialog_content = "Yakinlah, Tuanku, aku tidak akan mengecewakanmu!",
  str_homestory_N26dianying_90060301_12_dialog_content = "Sekarang jam 11:15 pagi... Mulai sekarang, kamu punya waktu tepat tiga hari untuk menemukan bilahnya dan membawanya kepadaku.",
  str_homestory_N26dianying_90060301_13_dialog_content = "(Tunggu... Apa dia bilang \"11:15\"?!)",
  str_homestory_N26dianying_90060301_14_dialog_content = "Eh, tuanku? Aku, uh... Aku baru menyadari bahwa aku masih perlu mengepak beberapa perbekalan sebelum berangkat dalam misi muliaku!",
  str_homestory_N26dianying_90060301_15_dialog_content = "Baiklah kalau begitu. Lihat persediaan Anda dan pergilah, tapi cepatlah!",
  str_homestory_N26dianying_90060301_16_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_17_dialog_content = "M-Master! Saya minta maaf atas sedikit keterlambatan!",
  str_homestory_N26dianying_90060301_18_dialog_content = "\"Sedikit,\" katamu? Anda terlambat tiga puluh menit.",
  str_homestory_N26dianying_90060301_19_dialog_content = "Sigh ... Tidak masalah. Saya telah memanggil Anda hari ini karena saya membutuhkan bantuan Anda dengan masalah yang paling penting.",
  str_homestory_N26dianying_90060301_20_dialog_content = "Tentunya, Anda pernah mendengar legenda Pedang Surgawi? \"Api perang telah merusak dunia kita selama bertahun-tahun sekarang ...\"",
  str_homestory_N26dianying_90060301_21_dialog_content = "Tuanku, mungkinkah... Anda juga ingin saya pergi ke Desa Naga untuk mencari Pedang Langit?",
  str_homestory_N26dianying_90060301_22_dialog_content = "Itu betul. Dengan menemukan Pedang Surgawi, Fraksi Zakura akan menertibkan dunia yang kacau ini, dan memantapkan tempatnya sebagai kekuatan terkuat yang ada.",
  str_homestory_N26dianying_90060301_23_dialog_content = "Tunggu... Apa maksudmu, \"juga\"?",
  str_homestory_N26dianying_90060301_24_dialog_content = "Oh! T-Tidak ada, Tuanku!",
  str_homestory_N26dianying_90060301_25_dialog_content = "(Jika utusan dari kedua faksi mengetahui bahwa aku menjalankan misi yang sama untuk mereka...)",
  str_homestory_N26dianying_90060301_26_dialog_content = "(Aku akan sama saja dengan mati!)",
  str_homestory_N26dianying_90060301_27_dialog_content = "Meskipun Anda masih kurang pengalaman, sumber saya memberi tahu saya bahwa pedang itu dapat ditemukan di suatu tempat di kampung halaman Anda, Desa Naga. Anda adalah satu-satunya orang yang dapat saya percayai dengan pencarian ini.",
  str_homestory_N26dianying_90060301_28_dialog_content = "<size=45>Baik tuan ku!</size>",
  str_homestory_N26dianying_90060301_29_dialog_content = "T-Namun, aku masih memiliki beberapa hal untuk didiskusikan dengan rekan-rekanku sebelum aku berangkat...",
  str_homestory_N26dianying_90060301_30_dialog_content = "Sangat baik, tetapi cobalah untuk tetap singkat. Oh, dan ingat untuk memeriksa cuaca untuk saya sebelum Anda pergi.",
  str_homestory_N26dianying_90060301_31_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_32_dialog_content = "M-Tuanku! Cuaca hari ini cerah, hari yang sempurna untuk melatih prajurit Anda!",
  str_homestory_N26dianying_90060301_33_dialog_content = "Hmm? Saya tidak ingat meminta Anda untuk laporan cuaca?",
  str_homestory_N26dianying_90060301_34_dialog_content = "(Oh, sial! Tuan yang salah!)",
  str_homestory_N26dianying_90060301_35_dialog_content = "Jika Anda sudah selesai dengan persiapan Anda, maka segera berangkat! Jika Anda berhasil, hadiah Anda akan berlimpah!",
  str_homestory_N26dianying_90060301_36_dialog_content = "Oh, dan jika Anda kebetulan melihat bunga matahari bermekaran selama perjalanan Anda, cari cara untuk mengirim kabar kepada saya. Dipahami?",
  str_homestory_N26dianying_90060301_37_dialog_content = "Baik tuan ku! Aku akan segera pergi!",
  str_homestory_N26dianying_90060301_38_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_39_dialog_content = "Aku kembali, tuanku! Bunga matahari bermekaran dan penuh biji! Mereka dapat dipanen kapan saja untuk jatah prajurit!",
  str_homestory_N26dianying_90060301_40_dialog_content = "Hmm? Dan kapan tepatnya saya meminta laporan tentang bunga matahari?",
  str_homestory_N26dianying_90060301_41_dialog_content = "Oh, dan selama perjalanan Anda, jika Anda melihat alang-alang telah tumbuh tinggi, cari cara untuk mengirim kabar kepada saya. Dipahami?",
  str_homestory_N26dianying_90060301_42_dialog_content = "Baik tuan ku! Aku akan segera pergi!",
  str_homestory_N26dianying_90060301_43_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_44_dialog_content = "Aku kembali, tuanku! Alang-alang sekarang tinggi dan padat, sempurna untuk menyembunyikan serangan mendadak pada musuh Anda!",
  str_homestory_N26dianying_90060301_45_dialog_content = "Oh? Dan kapan tepatnya saya meminta laporan tentang alang-alang?",
  str_homestory_N26dianying_90060301_46_dialog_content = "Oh, dan selama perjalanan Anda, jika Anda melihat bahwa ladang gandum telah mencapai kematangan penuh, temukan cara untuk mengirim kabar kepada saya. Dipahami?",
  str_homestory_N26dianying_90060301_47_dialog_content = "Baik tuan ku! Aku akan segera pergi!",
  str_homestory_N26dianying_90060301_48_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_49_dialog_content = "Aku kembali, tuanku! Ladang gandum sudah penuh dan siap panen! Para prajurit akan makan enak musim dingin ini!",
  str_homestory_N26dianying_90060301_50_dialog_content = "Oh? Dan kapan tepatnya saya meminta laporan tentang ladang gandum?",
  str_homestory_N26dianying_90060301_50X1_dialog_content = "Oh, dan selama perjalanan Anda, jika Anda melihat ada orang yang mencurigakan, cari cara untuk mengirim kabar kepada saya. Dipahami?",
  str_homestory_N26dianying_90060301_50X2_dialog_content = "Baik tuan ku! Aku akan segera pergi!",
  str_homestory_N26dianying_90060301_50X3_dialog_content = "Terkesiap, terkesiap, terkesiap...",
  str_homestory_N26dianying_90060301_50X4_dialog_content = "Aku kembali, tuanku! Tidak ada orang yang mencurigakan di sekitar. Kita bisa mulai mempersiapkan pelatihan!",
  str_homestory_N26dianying_90060301_50X5_dialog_content = "Hmm? Saya tidak ingat meminta Anda untuk melaporkan situasi terdekat kepada saya!",
  str_homestory_N26dianying_90060301_51_dialog_content = "(Sial! Tidak lagi!!)",
  str_homestory_N26dianying_90060301_52_dialog_content = "Jika Anda selesai mengucapkan selamat tinggal kepada teman-teman Anda, maka bergegaslah ke Desa Naga. Anda akan mendapatkan rasa terima kasih saya yang abadi jika Anda berhasil dalam pencarian Anda.",
  str_homestory_N26dianying_90060301_53_dialog_content = "Baik tuan ku! Aku akan segera pergi!",
  str_homestory_N26dianying_90060301_54_dialog_content = "(Tuanku, Anda adalah orang bijak dan kuat... Jadi tolong maafkan saya!)",
  str_homestory_N26dianying_90060301_55_dialog_content = "(Dua hadiah untuk harga satu misi... Terlalu bagus untuk dilewatkan!)",
  str_homestory_N26dianying_90060301_56_dialog_content = "Wah... Akhirnya aku berhasil sampai ke Desa Naga. Ini benar-benar membawaku kembali...",
  str_homestory_N26dianying_90060301_57_dialog_content = "Langkah ke atas dan lihatlah! Senjata luar biasa dari seluruh dunia! Pedang dan bilah suci berlimpah, semuanya dengan diskon besar-besaran!",
  str_homestory_N26dianying_90060301_58_dialog_content = "Ayo satu, ayo semua! Saya memiliki semua jenis pedang suci yang dijual di sini, tetapi Kerang Air Suci saya adalah bintang pertunjukan yang sesungguhnya!",
  str_homestory_N26dianying_90060301_59_dialog_content = "Apa? Maaf, apakah Anda mengatakan bahwa Anda memiliki pedang suci untuk dijual?",
  str_homestory_N26dianying_90060301_60_dialog_content = "Jika itu yang Anda cari, maka Anda telah datang ke tempat yang tepat! Heck, saya bahkan memiliki stok Heavenly Blade, jika Anda tertarik?",
  str_homestory_N26dianying_90060301_61_dialog_content = "Lihat pedang di rak senjata di sana? Saya bersedia berpisah dengannya untuk harga rendah, rendah 99.999.999 Nightium!",
  str_homestory_N26dianying_90060301_62_dialog_content = "Jika itu yang Anda cari, maka Anda telah datang ke tempat yang tepat! Heck, saya bahkan memiliki stok Heavenly Blade, jika Anda tertarik?",
  str_homestory_N26dianying_90060301_63_dialog_content = "Lihat pedang di rak senjata di sana? Saya bersedia berpisah dengannya untuk harga rendah, rendah 99.999.999 Nightium!",
  str_homestory_N26dianying_90060301_64_dialog_content = "Itu sangat mahal! Mungkinkah itu Pedang Surgawi dari legenda...?",
  str_homestory_N26dianying_90060301_65_dialog_content = "Heheheh... Lumayan kan? Anda memperhatikan kualitas, Nona!",
  str_homestory_N26dianying_90060301_66_dialog_content = "Cukup mengesankan, ya? Anda memperhatikan kualitas, Nona!",
  str_homestory_N26dianying_90060301_67_dialog_content = "Ini bukan Pedang Surgawi.",
  str_homestory_N26dianying_90060301_68_dialog_content = "Hah? B-Bagaimana kau tahu?!",
  str_homestory_N26dianying_90060301_69_dialog_content = "Hah? B-Bagaimana kau tahu?!",
  str_homestory_N26dianying_90060301_70_dialog_content = "Saya tidak bisa mengatakan dengan pasti bagaimana saya tahu... Sebut saja intuisi, saya kira?",
  str_homestory_N26dianying_90060301_71_dialog_content = "Ehem... Nah, Anda benar! Pedang itu sama sekali bukan Pedang Surgawi, karena yang asli...",
  str_homestory_N26dianying_90060301_72_dialog_content = "Apakah pedang tepat di sebelahnya!",
  str_homestory_N26dianying_90060301_73_dialog_content = "Ehem... Nah, kamu benar! Pedang itu sama sekali bukan Pedang Surgawi, karena yang asli...",
  str_homestory_N26dianying_90060301_74_dialog_content = "Apakah pedang tepat di sebelahnya!",
  str_homestory_N26dianying_90060301_75_dialog_content = "Betulkah? Izinkan aku melihat! ...Uh, maafkan aku, tapi yang ini juga bukan yang sebenarnya!",
  str_homestory_N26dianying_90060301_76_dialog_content = "(Sial... Jangan membodohi dia!)",
  str_homestory_N26dianying_90060301_77_dialog_content = "(Sial... Tidak ada yang membodohi dia!)",
  str_homestory_N26dianying_90060301_78_dialog_content = "Saya yakin Anda sudah tahu, tapi di Desa Naga ini, kami tidak mencoba menipu orang-orang kami sendiri. Sekarang bisakah Anda memberi tahu saya di mana saya dapat menemukan Pedang Surgawi yang asli?",
  str_homestory_N26dianying_90060301_79_dialog_content = "Baik, Anda menang... Ini dia.",
  str_homestory_N26dianying_90060301_80_dialog_content = "Baik, Anda menang... Ini dia.",
  str_homestory_N26dianying_90060301_81_dialog_content = "Sebuah rekaman video?!",
  str_homestory_N26dianying_90060301_82_dialog_content = "Letakkan kaset ini di proyektor di sana, dan tekan \"putar\".",
  str_homestory_N26dianying_90060301_83_dialog_content = "Proyektor akan menampilkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_84_dialog_content = "Letakkan kaset ini di proyektor di sana, dan tekan \"putar\".",
  str_homestory_N26dianying_90060301_85_dialog_content = "Proyektor akan menampilkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_86_dialog_content = "Hmm... Seharusnya mulai diputar saat aku menekan tombol ini, kan?",
  str_homestory_N26dianying_90060301_87_dialog_content = "... Hah? Mengapa gambar di kaset tidak bergerak? Gak ada suaranya juga...",
  str_homestory_N26dianying_90060301_88_dialog_content = "Tunggu, itu mulai bergerak!!",
  str_homestory_N26dianying_90060301_89_dialog_content = "Baik, Anda menang... Ini dia.",
  str_homestory_N26dianying_90060301_90_dialog_content = "Baik, Anda menang... Ini dia.",
  str_homestory_N26dianying_90060301_91_dialog_content = "... Sebuah peta?!",
  str_homestory_N26dianying_90060301_92_dialog_content = "Ambil peta ini, dan ikuti ke lokasi yang ditandai.",
  str_homestory_N26dianying_90060301_93_dialog_content = "Peta akan menunjukkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_94_dialog_content = "Ambil peta ini, dan ikuti ke lokasi yang ditandai.",
  str_homestory_N26dianying_90060301_95_dialog_content = "Peta akan menunjukkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_96_dialog_content = "Hmm... Aku cukup yakin aku mengambil jalan yang benar, bukan?",
  str_homestory_N26dianying_90060301_97_dialog_content = "Tetap saja, saya hampir tidak bisa membuat kepala atau ekor dari peta ini... Tulisan di atasnya juga hampir tidak terbaca...",
  str_homestory_N26dianying_90060301_98_dialog_content = "Hmm... Aku perlu melihat lebih dekat ini!",
  str_homestory_N26dianying_90060301_99_dialog_content = "Baik, kamu menang... Lihat ke sana.",
  str_homestory_N26dianying_90060301_100_dialog_content = "Baik, kamu menang... Lihat ke sana.",
  str_homestory_N26dianying_90060301_101_dialog_content = "Kotak surat?!",
  str_homestory_N26dianying_90060301_102_dialog_content = "Baca apa yang ditulis pemilik sebelumnya di atasnya.",
  str_homestory_N26dianying_90060301_103_dialog_content = "Kotak surat akan menampilkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_104_dialog_content = "Baca apa yang ditulis pemilik sebelumnya di atasnya.",
  str_homestory_N26dianying_90060301_105_dialog_content = "Kotak surat akan menampilkan jawaban yang Anda cari!",
  str_homestory_N26dianying_90060301_106_dialog_content = "Hmm... Kotak surat ini cukup tinggi ya?",
  str_homestory_N26dianying_90060301_107_dialog_content = "Tetapi bahkan dari bawah sini, saya dapat melihat bahwa tulisannya hampir terlalu ceroboh untuk dibaca...",
  str_homestory_N26dianying_90060301_108_dialog_content = "Hmm... Aku harus melihat lebih dekat ini!",
  str_homestory_N26dianying_90060301_108X1_dialog_content = "Baik, Anda menang... Ini dia. Menuju ke arah yang kuhadapi.",
  str_homestory_N26dianying_90060301_108X2_dialog_content = "Baik, Anda menang... Ini dia. Menuju ke arah yang kuhadapi.",
  str_homestory_N26dianying_90060301_108X3_dialog_content = "Kemana saya akan pergi?",
  str_homestory_N26dianying_90060301_108X4_dialog_content = "Um, jangan khawatir tentang itu. Teruslah berjalan maju!",
  str_homestory_N26dianying_90060301_108X5_dialog_content = "Selalu ada harapan baru di depan Anda di Desa Naga, negeri orang-orang luar biasa!",
  str_homestory_N26dianying_90060301_108X6_dialog_content = "Um, jangan khawatir tentang itu. Teruslah berjalan maju!",
  str_homestory_N26dianying_90060301_108X7_dialog_content = "Selalu ada harapan baru di depan Anda di Desa Naga, negeri orang-orang luar biasa!",
  str_homestory_N26dianying_90060301_108X8_dialog_content = "B-Benarkah!? Bukankah itu terlalu biasa...",
  str_homestory_N26dianying_90060301_108X9_dialog_content = "Ya ampun, aku benar. Aku sudah berjalan begitu lama... Bos pasti penipu!",
  str_homestory_N26dianying_90060301_108X10_dialog_content = "Hah? Mungkinkah ini...",
  str_homestory_N26dianying_90060301_109_dialog_content = "\"Cara dunia adalah untuk mencari keuntungan pribadi, dan untuk alasan ini, dunia tidak akan pernah berubah. Untuk mencegah Pedang Surgawi jatuh ke tangan orang jahat...\"",
  str_homestory_N26dianying_90060301_110_dialog_content = "\"Sebuah sumur kuno di Desa Naga diberkati dengan kekuatan untuk mengungkap pedang legendaris.\"",
  str_homestory_N26dianying_90060301_111_dialog_content = "\"Dipenuhi dengan Luminatics yang misterius, sumur ini tidak akan menunjukkan pantulan objek apa pun yang tertahan di perairannya.\"",
  str_homestory_N26dianying_90060301_112_dialog_content = "\"Ketika Pedang Surgawi sejati semakin dekat, citra dewanya akan muncul di dalam sumur...\"",
  str_homestory_N26dianying_90060301_113_dialog_content = "\"Cara dunia adalah untuk mencari keuntungan pribadi, dan untuk alasan ini, dunia tidak akan pernah berubah. Untuk mencegah Pedang Surgawi jatuh ke tangan orang jahat...\"",
  str_homestory_N26dianying_90060301_114_dialog_content = "\"Kursi santai di Desa Naga diberkati dengan kekuatan untuk mengungkap pedang legendaris.\"",
  str_homestory_N26dianying_90060301_115_dialog_content = "\"Dipenuhi dengan Luminatics yang misterius, kursi ini tidak akan membiarkan siapa pun beristirahat di kursinya.\"",
  str_homestory_N26dianying_90060301_116_dialog_content = "\"Ketika Pedang Surgawi sejati semakin dekat, gambar sucinya akan muncul di kursi...\"",
  str_homestory_N26dianying_90060301_117_dialog_content = "\"Cara dunia adalah mencari keuntungan pribadi, dan untuk alasan ini, dunia tidak akan pernah berubah. Untuk mencegah Pedang Surgawi jatuh ke tangan orang jahat...\"",
  str_homestory_N26dianying_90060301_118_dialog_content = "\"Sebuah piano di Desa Naga diberkati dengan kekuatan untuk mengungkap pedang legendaris.\"",
  str_homestory_N26dianying_90060301_119_dialog_content = "\"Dijiwai dengan Luminatics yang misterius, piano ini tidak akan mengizinkan siapa pun untuk memainkannya.\"",
  str_homestory_N26dianying_90060301_120_dialog_content = "\"Saat Pedang Surgawi sejati mendekat, citra dewanya akan muncul di atas tuts piano...\"",
  str_homestory_N26dianying_90060301_121_dialog_content = "... Yao? Apakah itu kamu Yao?",
  str_homestory_N26dianying_90060301_122_dialog_content = "Yao? Apakah itu benar-benar kamu?",
  str_homestory_N26dianying_90060301_123_dialog_content = "Ini aku, gadis tetangga sejak kami masih kecil! Aku sudah lama tidak melihatmu, Yao!",
  str_homestory_N26dianying_90060301_124_dialog_content = "Tidak sejak hari kamu meninggalkan desa untuk mencari pekerjaan... Kupikir aku tidak akan pernah melihatmu lagi!",
  str_homestory_N26dianying_90060301_125_dialog_content = "Omong-omong, apakah Anda kebetulan sedang mencari sesuatu?",
  str_homestory_N26dianying_90060301_126_dialog_content = "Setelah kita berdua meninggalkan desa untuk mencari pekerjaan... Kupikir aku tidak akan pernah melihatmu lagi!",
  str_homestory_N26dianying_90060301_127_dialog_content = "Omong-omong, apakah Anda sedang mencari sesuatu?",
  str_homestory_N26dianying_90060301_128_dialog_content = "Ceritanya panjang, tapi... Apakah Anda masih ingat di mana menemukan sumur itu? Anda tahu salah satunya, bukan?",
  str_homestory_N26dianying_90060301_129_dialog_content = "Ceritanya panjang, tapi... Apakah Anda masih ingat di mana menemukan kursi santai itu? Anda tahu salah satunya, bukan?",
  str_homestory_N26dianying_90060301_130_dialog_content = "Ceritanya panjang, tapi... Masih ingat di mana menemukan piano itu? Anda tahu salah satunya, kan?",
  str_homestory_N26dianying_90060301_131_dialog_content = "Tentu, ikuti saja saya dan saya akan menunjukkannya kepada Anda.",
  str_homestory_N26dianying_90060301_132_dialog_content = "Ini dia!",
  str_homestory_N26dianying_90060301_133_dialog_content = "Tentu, ikuti saja saya dan saya akan menunjukkannya kepada Anda.",
  str_homestory_N26dianying_90060301_134_dialog_content = "Baiklah, ini dia!",
  str_homestory_N26dianying_90060301_135_dialog_content = "Jadi... Apa kau benar-benar pulang hanya untuk melihat sumur ini?",
  str_homestory_N26dianying_90060301_136_dialog_content = "Jadi... Apakah Anda benar-benar pulang hanya untuk melihat kursi ini?",
  str_homestory_N26dianying_90060301_137_dialog_content = "Jadi... Apakah Anda benar-benar pulang hanya untuk melihat piano ini?",
  str_homestory_N26dianying_90060301_138_dialog_content = "Yah, sebenarnya... Aku datang untuk mencari petunjuk tentang keberadaan Heavenly Blade.",
  str_homestory_N26dianying_90060301_139_dialog_content = "Tuanku memerintahkanku untuk menemukannya, dan membawanya kembali kepada mereka secepat mungkin.",
  str_homestory_N26dianying_90060301_140_dialog_content = "<color=#FFB400>\"Tuan\"</color>? Seperti dalam \"lebih dari satu\"?",
  str_homestory_N26dianying_90060301_141_dialog_content = "<color=#FFB400>\"Tuan\"</color>? Seperti dalam \"lebih dari satu\"? ...Oh, maksudmu bosmu!",
  str_homestory_N26dianying_90060301_142_dialog_content = "Itu benar... Keduanya mempercayakanku dengan quest yang sama, di waktu yang sama persis, jadi aku disini.",
  str_homestory_N26dianying_90060301_143_dialog_content = "Meskipun, saya tidak yakin apa yang akan saya lakukan setelah menemukannya... Bagaimana saya harus memutuskan kepada siapa akan memberikannya?",
  str_homestory_N26dianying_90060301_144_dialog_content = "Mengapa tidak memiliki \"tuan\" Anda <color=#FFB400>berkelahi satu sama lain</color> untuk itu?",
  str_homestory_N26dianying_90060301_145_dialog_content = "Bagaimanapun, air di sumur ini benar-benar keruh. Saya tidak melihat \"gambar ilahi\" di mana pun di sini ...",
  str_homestory_N26dianying_90060301_146_dialog_content = "Ngomong-ngomong, kursi ini benar-benar kosong. Saya tidak melihat \"gambar ilahi\" di mana pun di atasnya ...",
  str_homestory_N26dianying_90060301_147_dialog_content = "Bagaimanapun, tuts piano ini tidak bernoda. Saya tidak melihat \"gambar ilahi\" di mana pun pada mereka ...",
  str_homestory_N26dianying_90060301_147X1_dialog_content = "... Yao? Apakah itu kamu Yao?",
  str_homestory_N26dianying_90060301_147X2_dialog_content = "Yao? Apakah itu benar-benar kamu?",
  str_homestory_N26dianying_90060301_147X3_dialog_content = "Ini aku, gadis tetangga sejak kami masih kecil! Aku sudah lama tidak melihatmu, Yao!",
  str_homestory_N26dianying_90060301_147X4_dialog_content = "Tidak sejak hari kamu meninggalkan desa untuk mencari pekerjaan... Kupikir aku tidak akan pernah melihatmu lagi!",
  str_homestory_N26dianying_90060301_147X5_dialog_content = "Omong-omong, apakah Anda sedang mencari sesuatu?",
  str_homestory_N26dianying_90060301_147X6_dialog_content = "Setelah kita berdua meninggalkan desa untuk mencari pekerjaan... Kupikir aku tidak akan pernah melihatmu lagi!",
  str_homestory_N26dianying_90060301_147X7_dialog_content = "Ngomong-ngomong, apa yang kamu lakukan?",
  str_homestory_N26dianying_90060301_147X8_dialog_content = "Um, jangan sebutkan itu. Kedua tuanku memintaku untuk mencari Pedang Surgawi yang sama.",
  str_homestory_N26dianying_90060301_147X9_dialog_content = "Pada akhirnya, saya tidak dapat menemukan apa pun ...",
  str_homestory_N26dianying_90060301_147X10_dialog_content = "Jadi selama ini Anda telah melayani dua tuan! Dan setelah saya sangat mempercayai Anda!",
  str_homestory_N26dianying_90060301_147X11_dialog_content = "L-Tuan Zakura?! A-Apa yang kau lakukan disini...?",
  str_homestory_N26dianying_90060301_147X12_dialog_content = "Aku seharusnya menanyakan pertanyaan yang sama padamu! Kata-kata tidak bisa mengungkapkan betapa kecewanya aku padamu, yang disebut \"hamba yang setia\"!",
  str_homestory_N26dianying_90060301_147X13_dialog_content = "L-Lord Dragonscorch?! Kamu di sini juga?!",
  str_homestory_N26dianying_90060301_147X14_dialog_content = "Uh... A-Apa yang terjadi di sini?",
  str_homestory_N26dianying_90060301_147X15_dialog_content = "Uh... A-Apa yang terjadi di sini?",
  str_homestory_N26dianying_90060301_147X16_dialog_content = "Uh-oh... Sepertinya jig sudah habis! Chubb!",
  str_homestory_N26dianying_90060301_147X17_dialog_content = "Saya khawatir tugas ini terlalu besar untuk Anda sendiri, jadi saya mengatur seseorang untuk mengikuti Anda selama pencarian Anda ...",
  str_homestory_N26dianying_90060301_147X18_dialog_content = "Dan laporkan semuanya kepadaku saat itu terjadi. Itu seharusnya berfungsi sebagai ujian atas kemampuan Anda.",
  str_homestory_N26dianying_90060301_147X19_dialog_content = "Ketika saya mengetahui bahwa pencarian Anda mulai membuahkan hasil, saya bergegas untuk membantu Anda menemukan Pedang Surgawi ...",
  str_homestory_N26dianying_90060301_147X20_dialog_content = "Hanya untuk mendengar Anda mengucapkan kata-kata yang mengerikan dan mengerikan itu!",
  str_homestory_N26dianying_90060301_147X21_dialog_content = "Sehat? Apa yang harus Anda katakan untuk pembelaan Anda, pengkhianat ?!",
  str_homestory_N26dianying_90060301_147X22_dialog_content = "Yah... karena semuanya sudah begini, aku akan bertanggung jawab untuk itu!",
  str_homestory_N26dianying_90060301_147X23_dialog_content = "Ambil tindakan, tuanku! Saya tahu aturannya. Hari ini adalah hari aku mati!",
  str_homestory_N26dianying_90060301_147X24_dialog_content = "Hah?",
  str_homestory_N26dianying_90060301_147X25_dialog_content = "Membunuhmu? Lelucon macam apa ini?",
  str_homestory_N26dianying_90060301_147X26_dialog_content = "Sebagai seorang pejuang yang bangga, saya tidak akan pernah membunuh lawan yang tidak bersenjata.",
  str_homestory_N26dianying_90060301_147X27_dialog_content = "Terlepas dari pengkhianatanmu, penyesalanmu tampak tulus... Baiklah, pelayanku. Mari kita pulang, sehingga Anda dapat dihukum sesuai.",
  str_homestory_N26dianying_90060301_147X28_dialog_content = "Apa? Aku yang pertama tiba, jadi hukuman Dragonscorch harus didahulukan!",
  str_homestory_N26dianying_90060301_147X29_dialog_content = "Saya katakan Zakura!",
  str_homestory_N26dianying_90060301_147X30_dialog_content = "Saya katakan Dragonscorch!",
  str_homestory_N26dianying_90060301_147X31_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_147X32_dialog_content = "Tolong, Tuanku... Ini bukan sesuatu yang harus kalian perebutkan...",
  str_homestory_N26dianying_90060301_148_dialog_content = "Jadi selama ini Anda telah melayani dua tuan! Dan setelah saya sangat mempercayai Anda!",
  str_homestory_N26dianying_90060301_149_dialog_content = "L-Tuan Zakura?! A-Apa yang kau lakukan disini...?",
  str_homestory_N26dianying_90060301_150_dialog_content = "Aku seharusnya menanyakan pertanyaan yang sama padamu! Kata-kata tidak bisa mengungkapkan betapa kecewanya aku padamu, yang disebut \"hamba yang setia\"!",
  str_homestory_N26dianying_90060301_151_dialog_content = "L-Lord Dragonscorch?! Kamu di sini juga?!",
  str_homestory_N26dianying_90060301_152_dialog_content = "Uh... A-Apa yang terjadi di sini?",
  str_homestory_N26dianying_90060301_153_dialog_content = "Uh... A-Apa yang terjadi di sini?",
  str_homestory_N26dianying_90060301_154_dialog_content = "Uh-oh... Sepertinya jig sudah habis! Chubb!",
  str_homestory_N26dianying_90060301_155_dialog_content = "Saya khawatir tugas ini terlalu besar untuk Anda sendiri, jadi saya mengatur seseorang untuk mengikuti Anda selama pencarian Anda ...",
  str_homestory_N26dianying_90060301_156_dialog_content = "Dan laporkan semuanya kepadaku saat itu terjadi. Itu seharusnya berfungsi sebagai ujian atas kemampuan Anda.",
  str_homestory_N26dianying_90060301_157_dialog_content = "Ketika saya mengetahui bahwa pencarian Anda mulai membuahkan hasil, saya bergegas untuk membantu Anda menemukan Pedang Surgawi ...",
  str_homestory_N26dianying_90060301_158_dialog_content = "Hanya untuk mendengar Anda mengucapkan kata-kata yang mengerikan dan mengerikan itu!",
  str_homestory_N26dianying_90060301_159_dialog_content = "Sehat? Apa yang harus Anda katakan untuk pembelaan Anda, pengkhianat ?!",
  str_homestory_N26dianying_90060301_160_dialog_content = "Eh?!",
  str_homestory_N26dianying_90060301_161_dialog_content = "Anda berani mengejek saya ?!",
  str_homestory_N26dianying_90060301_162_dialog_content = "(Mereka berpikir persis sama, bukan...)",
  str_homestory_N26dianying_90060301_163_dialog_content = "Mereka serempak! Chubb!",
  str_homestory_N26dianying_90060301_164_dialog_content = "Tuan Dragonscorch... Ini pasti takdir. Waktu apa yang lebih baik untuk memutuskan, sekali dan untuk selamanya, siapa yang terkuat... Daripada sekarang!",
  str_homestory_N26dianying_90060301_165_dialog_content = "Kau mengeluarkan kata-kata itu dari mulutku. Hari ini adalah hari di mana Dragonscorch membuktikan keunggulannya!",
  str_homestory_N26dianying_90060301_166_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_167_dialog_content = "(Oh sial... Mereka akan saling mencabik-cabik! Aku harus melakukan sesuatu tentang ini...)",
  str_homestory_N26dianying_90060301_168_option_content = "Temukan Pedang Surgawi!",
  str_homestory_N26dianying_90060301_169_dialog_content = "Hai! Jangan lupa tujuan pencarian Anda!",
  str_homestory_N26dianying_90060301_170_dialog_content = "Itu benar! Yang paling penting saat ini... Adalah menemukan Pedang Surgawi!",
  str_homestory_N26dianying_90060301_171_dialog_content = "Mungkin jika saya melihat lebih dekat, \"citra ilahi\" akan muncul ...",
  str_homestory_N26dianying_90060301_172_dialog_content = "H-hah?!",
  str_homestory_N26dianying_90060301_173_dialog_content = "Tuanku! Ayo lihat, cepat!",
  str_homestory_N26dianying_90060301_174_dialog_content = "Hmm?",
  str_homestory_N26dianying_90060301_175_dialog_content = "Mungkinkah... Pedang Langit?!",
  str_homestory_N26dianying_90060301_176_dialog_content = "Apa ini...?",
  str_homestory_N26dianying_90060301_177_dialog_content = "Mengapa pedangku bersinar seperti ini?",
  str_homestory_N26dianying_90060301_178_dialog_content = "Yah, sudah waktunya! Akhirnya, Pedang Surgawi telah bersatu sekali lagi!",
  str_homestory_N26dianying_90060301_179_dialog_content = "Yah, sudah waktunya! Akhirnya, Pedang Langit telah bersatu sekali lagi!",
  str_homestory_N26dianying_90060301_180_dialog_content = "Maksudmu…",
  str_homestory_N26dianying_90060301_181_dialog_content = "Itu benar! Yang disebut \"Pedang Surgawi\"... Sebenarnya adalah sepasang pedang! Dan hanya ketika mereka disatukan, kekuatan sejati mereka akhirnya akan terungkap dengan sendirinya.",
  str_homestory_N26dianying_90060301_182_dialog_content = "Dahulu kala, saya mendapat hak istimewa untuk menyaksikan dua pejuang hebat memotong banyak Eclipsites dengan dua bilah ini ...",
  str_homestory_N26dianying_90060301_183_dialog_content = "Itu benar! Sebenarnya ada DUA Pedang Surgawi, dan kekuatan mereka yang sebenarnya hanya akan terungkap dengan sendirinya saat disatukan!",
  str_homestory_N26dianying_90060301_184_dialog_content = "Ketika saya masih kecil, saya melihat dua prajurit legendaris memotong pasukan Eclipsites dengan dua bilah ini ...",
  str_homestory_N26dianying_90060301_185_dialog_content = "Itu terakhir kali kedua pedang itu digunakan bersamaan. Setelah pertempuran itu, mereka jatuh ke tangan yang terpisah dan sejak itu dijauhkan satu sama lain.",
  str_homestory_N26dianying_90060301_186_dialog_content = "Itu terakhir kali kedua pedang itu digunakan bersamaan. Setelah pertempuran itu, mereka jatuh ke tangan yang terpisah dan sejak itu dijauhkan satu sama lain.",
  str_homestory_N26dianying_90060301_187_dialog_content = "Tapi sekarang, Heavenly Blade utuh sekali lagi!",
  str_homestory_N26dianying_90060301_188_dialog_content = "Tapi sekarang, Heavenly Blade utuh sekali lagi!",
  str_homestory_N26dianying_90060301_189_dialog_content = "I-Itu benar, tuanku! Terlepas dari perbedaan Anda, tujuan Anda adalah satu dan sama ... Anda bahkan berpikir sangat mirip!",
  str_homestory_N26dianying_90060301_190_dialog_content = "Alih-alih bertarung di antara kalian sendiri, mengapa tidak menggabungkan kekuatan kalian dan menyelamatkan dunia bersama?",
  str_homestory_N26dianying_90060301_191_dialog_content = "Hmm…",
  str_homestory_N26dianying_90060301_192_dialog_content = "Eh...",
  str_homestory_N26dianying_90060301_193_dialog_content = "Pembantu membuat poin yang valid... Lagipula, kita berdua mencari kekuatan Pedang Surgawi.",
  str_homestory_N26dianying_90060301_194_dialog_content = "Dan jika kami menggabungkan kekuatan kami, kami akan tetap menjadi pemimpin faksi paling kuat di dunia.",
  str_homestory_N26dianying_90060301_195_dialog_content = "Adapun Anda, hamba \"setia\" kami ...",
  str_homestory_N26dianying_90060301_196_dialog_content = "Oh, tidak...",
  str_homestory_N26dianying_90060301_197_dialog_content = "Anda telah membuktikan nilai Anda, dan Zakura akan selamanya berutang budi kepada Anda!",
  str_homestory_N26dianying_90060301_198_dialog_content = "Dragonscorch juga berhutang banyak pada usaha kerasmu!",
  str_homestory_N26dianying_90060301_199_dialog_content = "<size=45>Tuanku!</size>",
  str_homestory_N26dianying_90060301_200_dialog_content = "Heheheh... Maka, lahirlah legenda baru!",
  str_homestory_N26dianying_90060301_201_dialog_content = "Heehee! Maka, lahirlah legenda baru!",
  str_homestory_N26dianying_90060301_202_dialog_content = "\"Pada akhirnya, Zakura dan Dragonscorch mengesampingkan perbedaan mereka dan bergabung menjadi satu pasukan yang kuat.\"",
  str_homestory_N26dianying_90060301_203_dialog_content = "\"Dengan kekuatan gabungan mereka, serta kekuatan Pedang Surgawi, dunia diberkati dengan kedamaian sekali lagi.\"",
  str_homestory_N26dianying_90060301_204_dialog_content = "\"Pada akhirnya, Zakura dan Dragonscorch mengesampingkan perbedaan mereka dan bergabung menjadi satu pasukan yang kuat.\"",
  str_homestory_N26dianying_90060301_205_dialog_content = "\"Dengan kekuatan gabungan mereka, serta kekuatan Pedang Surgawi, dunia diberkati dengan kedamaian sekali lagi.\"",
  str_homestory_N26dianying_90060301_206_option_content = "Cobalah untuk menebus kesalahan!",
  str_homestory_N26dianying_90060301_207_dialog_content = "Anda tahu keduanya lebih baik daripada orang lain! Pergi bekerja hal-hal di antara mereka!",
  str_homestory_N26dianying_90060301_208_dialog_content = "Itu benar! Sebagai pelayan mereka, hanya aku yang bisa menyelesaikan perbedaan mereka!",
  str_homestory_N26dianying_90060301_209_dialog_content = "Tuanku, jika saya boleh berbicara? Terlepas dari perbedaan Anda, tujuan Anda sama ... Anda bahkan berpikir sangat mirip!",
  str_homestory_N26dianying_90060301_210_dialog_content = "Alih-alih bertarung di antara kalian sendiri, mengapa tidak menggabungkan kekuatan kalian dan menyelamatkan dunia bersama?",
  str_homestory_N26dianying_90060301_211_dialog_content = "Hmm…",
  str_homestory_N26dianying_90060301_212_dialog_content = "Eh...",
  str_homestory_N26dianying_90060301_213_dialog_content = "Pelayan membuat poin yang valid. Sebagai pemimpin dari faksi kita masing-masing, adalah tugas kita untuk melindungi dunia dari ancaman Eclipsite.",
  str_homestory_N26dianying_90060301_214_dialog_content = "Dan jika kami menggabungkan kekuatan kami, kami akan tetap menjadi pemimpin faksi paling kuat di dunia.",
  str_homestory_N26dianying_90060301_215_dialog_content = "Adapun Anda, hamba \"setia\" kami ...",
  str_homestory_N26dianying_90060301_216_dialog_content = "Oh, tidak...",
  str_homestory_N26dianying_90060301_217_dialog_content = "Meskipun kau gagal dalam pencarianmu untuk menemukan Heavenly Blade... Mungkin ada cara lain untuk menyelamatkan dunia.",
  str_homestory_N26dianying_90060301_218_dialog_content = "Jika Dragonscorch dan Zakura menjadi satu, tidak perlu menghukummu karena pengkhianatanmu.",
  str_homestory_N26dianying_90060301_219_dialog_content = "<size=45>Tuanku!</size>",
  str_homestory_N26dianying_90060301_220_dialog_content = "Heheheh... Maka, lahirlah legenda baru!",
  str_homestory_N26dianying_90060301_221_dialog_content = "Heehee! Maka, lahirlah legenda baru!",
  str_homestory_N26dianying_90060301_222_dialog_content = "\"Pada akhirnya, Zakura dan Dragonscorch mengesampingkan perbedaan mereka dan bergabung menjadi satu pasukan yang kuat.\"",
  str_homestory_N26dianying_90060301_223_dialog_content = "\"Jadi, dunia diberkati dengan kedamaian sekali lagi.\"",
  str_homestory_N26dianying_90060301_224_dialog_content = "\"Pada akhirnya, Zakura dan Dragonscorch mengesampingkan perbedaan mereka dan bergabung menjadi satu pasukan yang kuat.\"",
  str_homestory_N26dianying_90060301_225_dialog_content = "\"Jadi, dunia diberkati dengan kedamaian sekali lagi.\"",
  str_homestory_N26dianying_90060301_226_option_content = "Bunuh saja aku!",
  str_homestory_N26dianying_90060301_227_dialog_content = "A-Apa yang harus aku lakukan? Saya tidak melihat cara untuk memperbaikinya lagi ...",
  str_homestory_N26dianying_90060301_228_dialog_content = "Tidak, tunggu... Ini salahku jadi begini. Aku harus bertanggung jawab atas perbuatanku...",
  str_homestory_N26dianying_90060301_229_dialog_content = "Tuanku! Akulah yang harus disalahkan atas semua ini! Jika kau akan membunuh seseorang, bunuh aku!",
  str_homestory_N26dianying_90060301_230_dialog_content = "Hah?",
  str_homestory_N26dianying_90060301_231_dialog_content = "Membunuhmu? Lelucon macam apa ini?",
  str_homestory_N26dianying_90060301_232_dialog_content = "Sebagai seorang pejuang yang bangga, saya tidak akan pernah membunuh lawan yang tidak bersenjata.",
  str_homestory_N26dianying_90060301_233_dialog_content = "Terlepas dari pengkhianatanmu, penyesalanmu tampak tulus... Baiklah, pelayanku. Mari kita pulang, sehingga Anda dapat dihukum sesuai.",
  str_homestory_N26dianying_90060301_234_dialog_content = "Apa? Aku yang pertama tiba, jadi hukuman Dragonscorch harus didahulukan!",
  str_homestory_N26dianying_90060301_235_dialog_content = "Saya katakan Zakura!",
  str_homestory_N26dianying_90060301_236_dialog_content = "Saya katakan Dragonscorch!",
  str_homestory_N26dianying_90060301_237_dialog_content = "Hoo-ah!",
  str_homestory_N26dianying_90060301_238_dialog_content = "Tolong, tuanku... Ini bukan sesuatu yang harus kalian perebutkan...",
  str_homestory_N26dianying_90060301_239_dialog_content = "Jika saya ingat dengan benar, toko ini menjual beberapa senjata terbaik di seluruh Desa Naga!",
  str_homestory_N26dianying_90060301_240_dialog_content = "Hah?!",
  str_homestory_N26dianying_90060301_241_dialog_content = "Apa yang terjadi dengan semua senjata itu? Toko benar-benar kosong!",
  str_homestory_N26dianying_90060301_242_dialog_content = "Jangan ingatkan saya... Maaf teman, tapi saya tutup untuk selamanya.",
